/**
 * 正式男女预设 pf_01–10。配置不合法则加载失败，不静默跳过。
 * 以 face_redraw 被采纳为前提。招募不读 init；init 只作创角初值。
 */
import type { Gender, HeadCompat } from './types_MT';
import { LOOK_SCHEMA, LIB_VERSION, type AgeBand, type LookV3 } from './appearance_MT';
import type { LookRecipe, RecruitLibrary, BeardEntry } from './recruit_MT';
import { SKIN_IDS, OFFICIAL_HAIR_IDS } from './palette_MT';
import defaultPresetsJson from './data/face_presets_v1.json';

export const PRESET_SCHEMA = 'v1.face_presets.1';
export const PRESET_IDS = [
  'pf_01',
  'pf_02',
  'pf_03',
  'pf_04',
  'pf_05',
  'pf_06',
  'pf_07',
  'pf_08',
  'pf_09',
  'pf_10',
] as const;
export type OfficialPresetId = (typeof PRESET_IDS)[number];

export interface PresetInit {
  hair: string;
  skinTone: string;
  hairColor: string;
}

export interface FacePresetRecipe extends LookRecipe {
  init: PresetInit;
}

export interface FacePresetsFile {
  schema: string;
  libVersion: number;
  socketSet: string;
  note?: string;
  aliases: Record<string, string>;
  m: Record<AgeBand, FacePresetRecipe[]>;
  f: Record<AgeBand, FacePresetRecipe[]>;
}

export const DEFAULT_FACE_PRESETS = defaultPresetsJson as FacePresetsFile;

export type PresetFailCode =
  | 'PRESET_ID_UNKNOWN'
  | 'PRESET_SOCKET_MIX'
  | 'PRESET_BROW_REQUIRED'
  | 'PRESET_NOSE_CONFLICT'
  | 'PRESET_BEARD_RULE'
  | 'PRESET_MATURE_MARK'
  | 'PRESET_COUNT'
  | 'PRESET_INIT_PALETTE'
  | 'PRESET_DUP'
  | 'RECRUIT_HAIRCOLOR_POOL';

export interface PresetIssue {
  code: PresetFailCode;
  message: string;
  detail?: unknown;
}

export interface PresetValidation {
  ok: boolean;
  issues: PresetIssue[];
}

function issue(code: PresetFailCode, message: string, detail?: unknown): PresetIssue {
  return detail !== undefined ? { code, message, detail } : { code, message };
}

export function resolvePresetId(preset: string | null | undefined, file: FacePresetsFile = DEFAULT_FACE_PRESETS): string | null {
  if (preset == null || preset === '') return null;
  return file.aliases[preset] ?? preset;
}

export function clonePresets(file: FacePresetsFile = DEFAULT_FACE_PRESETS): FacePresetsFile {
  return JSON.parse(JSON.stringify(file)) as FacePresetsFile;
}

function bandsOf(file: FacePresetsFile, gender: Gender): { ageBand: AgeBand; rec: FacePresetRecipe }[] {
  const g = file[gender];
  return [
    ...(g.youth ?? []).map((rec) => ({ ageBand: 'youth' as const, rec })),
    ...(g.mature ?? []).map((rec) => ({ ageBand: 'mature' as const, rec })),
  ];
}

export function listPresets(gender: Gender, file: FacePresetsFile = DEFAULT_FACE_PRESETS): { ageBand: AgeBand; rec: FacePresetRecipe }[] {
  return bandsOf(file, gender);
}

export function findPreset(
  gender: Gender,
  presetId: string | null | undefined,
  file: FacePresetsFile = DEFAULT_FACE_PRESETS,
): { ageBand: AgeBand; rec: FacePresetRecipe } | null {
  const id = resolvePresetId(presetId, file);
  if (!id) return null;
  return bandsOf(file, gender).find((r) => r.rec.id === id) ?? null;
}

function rowOf(compat: HeadCompat | undefined, gender: Gender, partSet: string) {
  return compat?.byGenderPartSet?.[gender]?.[partSet];
}

function tagsOf(compat: HeadCompat | undefined, partSet: string): string[] {
  if (!compat) return [];
  const row =
    compat.byId?.[Object.keys(compat.byId ?? {}).find((id) => compat.byId[id]!.partSet === partSet) ?? ''] ??
    (compat.entries ?? []).find((e) => e.partSet === partSet && Array.isArray(e.tags));
  const fromGender = compat.byGenderPartSet?.m?.[partSet]?.tags;
  return (fromGender ?? row?.tags ?? []) as string[];
}

function noseBakedOf(compat: HeadCompat, gender: Gender, face: string): boolean | undefined {
  const row = rowOf(compat, gender, face);
  if (typeof row?.noseBaked === 'boolean') return row.noseBaked;
  const hit = compat.entries.find(
    (e) => e.gender === gender && e.partSet === face && typeof e.noseBaked === 'boolean',
  );
  return hit?.noseBaked;
}

const FEATURE_KEYS = ['face', 'eyes', 'brow', 'mouth', 'nose', 'beard', 'mark'] as const;

/**
 * V1–V9。任一失败则配置不能加载。
 */
export function validateFacePresets(file: FacePresetsFile, compat: HeadCompat): PresetValidation {
  const issues: PresetIssue[] = [];
  const expectedSocket = file.socketSet || 'redraw_1110';

  for (const gender of ['m', 'f'] as const) {
    const youth = file[gender].youth ?? [];
    const mature = file[gender].mature ?? [];
    const all = [...youth, ...mature];
    const ids = all.map((r) => r.id);

    if (youth.length !== 6 || mature.length !== 4 || ids.length !== 10) {
      issues.push(issue('PRESET_COUNT', `${gender} 库青年须 6、熟龄须 4，实际 youth=${youth.length} mature=${mature.length}`, { gender, youth: youth.length, mature: mature.length }));
    }
    const expected = new Set(PRESET_IDS);
    const got = new Set(ids);
    const missing = [...expected].filter((id) => !got.has(id));
    const extra = ids.filter((id, i) => !expected.has(id as OfficialPresetId) || ids.indexOf(id) !== i);
    if (missing.length || extra.length || got.size !== ids.length) {
      issues.push(issue('PRESET_COUNT', `${gender} 库 id 必须是不重复的 pf_01–10`, { gender, ids, missing, extra }));
    }

    const tuples = new Map<string, string[]>();
    for (const { ageBand, rec } of bandsOf(file, gender)) {
      const loc = `${gender}/${ageBand}/${rec.id}`;
      if (!rec.brow) {
        issues.push(issue('PRESET_BROW_REQUIRED', `${loc} brow 必须非空且属于该性别库`, { loc, brow: rec.brow }));
      }

      const idChecks: { key: string; id: string | null }[] = [
        { key: 'face', id: rec.face },
        { key: 'eyes', id: rec.eyes },
        { key: 'brow', id: rec.brow },
        { key: 'mouth', id: rec.mouth },
        { key: 'nose', id: rec.nose },
        { key: 'beard', id: rec.beard },
        { key: 'mark', id: rec.mark },
        { key: 'hair', id: rec.init?.hair ?? null },
      ];
      for (const { key, id } of idChecks) {
        if (id == null || id === '') continue;
        const row = rowOf(compat, gender, id);
        if (!row) {
          issues.push(issue('PRESET_ID_UNKNOWN', `${loc} ${key}=${id} 不在该性别 head_compat 生效表`, { loc, key, id }));
          continue;
        }
        if (row.socketSet !== expectedSocket) {
          issues.push(issue('PRESET_SOCKET_MIX', `${loc} ${key}=${id} socketSet=${row.socketSet}，不能与 ${expectedSocket} 混用`, { loc, key, id, socketSet: row.socketSet }));
        }
      }

      const baked = rec.face ? noseBakedOf(compat, gender, rec.face) : undefined;
      if (baked === true && rec.nose != null) {
        issues.push(issue('PRESET_NOSE_CONFLICT', `${loc} noseBaked:true 时 nose 必须为 null`, { loc, face: rec.face, nose: rec.nose }));
      }
      if (baked === false && (rec.nose == null || rec.nose === '')) {
        issues.push(issue('PRESET_NOSE_CONFLICT', `${loc} noseBaked:false 时 nose 必须非空`, { loc, face: rec.face, nose: rec.nose }));
      }

      if (gender === 'f' && rec.beard != null) {
        issues.push(issue('PRESET_BEARD_RULE', `${loc} 女库 beard 必须为 null`, { loc, beard: rec.beard }));
      }
      if (gender === 'm' && rec.beard != null) {
        if (!String(rec.beard).startsWith('bd_')) {
          issues.push(issue('PRESET_BEARD_RULE', `${loc} 男库 beard 必须为 null 或 bd_*`, { loc, beard: rec.beard }));
        } else if (ageBand === 'youth') {
          const tags = tagsOf(compat, rec.beard);
          if (!tags.includes('stubble') && !tags.includes('short')) {
            issues.push(issue('PRESET_BEARD_RULE', `${loc} 青年带须款必须有 stubble 或 short 标签`, { loc, beard: rec.beard, tags }));
          }
        }
      }

      if (ageBand === 'mature' && (rec.mark == null || rec.mark === '')) {
        issues.push(issue('PRESET_MATURE_MARK', `${loc} 熟龄 mark 必须非空`, { loc, mark: rec.mark }));
      }

      const skin = rec.init?.skinTone;
      const hc = rec.init?.hairColor;
      if (!skin || !(SKIN_IDS as readonly string[]).includes(skin) || !hc || !(OFFICIAL_HAIR_IDS as readonly string[]).includes(hc)) {
        issues.push(issue('PRESET_INIT_PALETTE', `${loc} init.skinTone 须为 skin_01–06，init.hairColor 须为 hc_01–06`, { loc, init: rec.init }));
      }

      const tuple = FEATURE_KEYS.map((k) => rec[k] ?? '').join('|');
      const key = `${gender}|${ageBand}|${tuple}`;
      const holders = tuples.get(key) ?? [];
      holders.push(rec.id);
      tuples.set(key, holders);
    }
    for (const [key, holders] of tuples) {
      if (holders.length > 1) {
        issues.push(issue('PRESET_DUP', `同库同年龄段五官七元组重复：${key} → ${holders.join(',')}`, { key, holders }));
      }
    }
  }

  return { ok: issues.length === 0, issues };
}

/** V10：招募发色池只含 hc_01–06。 */
export function validateRecruitHairColorPool(pool: readonly string[]): PresetValidation {
  const issues: PresetIssue[] = [];
  const official = new Set(OFFICIAL_HAIR_IDS);
  const unexpected = pool.filter((id) => !official.has(id as (typeof OFFICIAL_HAIR_IDS)[number]));
  const missing = OFFICIAL_HAIR_IDS.filter((id) => !pool.includes(id));
  if (unexpected.length || missing.length || pool.length !== 6) {
    issues.push(
      issue('RECRUIT_HAIRCOLOR_POOL', '招募发色随机池只含 hc_01–06，不含 hc_07–10', { pool: [...pool], unexpected, missing }),
    );
  }
  return { ok: issues.length === 0, issues };
}

export function recipesToLibrary(
  file: FacePresetsFile,
  gender: Gender,
  compat?: HeadCompat,
): Record<AgeBand, LookRecipe[]> {
  const mapRec = (rec: FacePresetRecipe): LookRecipe => ({
    id: rec.id,
    face: rec.face,
    eyes: rec.eyes,
    brow: rec.brow,
    mouth: rec.mouth,
    nose: rec.nose,
    beard: rec.beard,
    mark: rec.mark,
    init: rec.init,
  });
  void compat;
  return {
    youth: (file[gender].youth ?? []).map(mapRec),
    mature: (file[gender].mature ?? []).map(mapRec),
  };
}

function defaultBeardTags(id: string): string[] {
  const map: Record<string, string[]> = {
    bd_01: ['stubble', 'short'],
    bd_02: ['mustache', 'short'],
    bd_03: ['jawline', 'short'],
    bd_04: ['goatee', 'short'],
    bd_05: ['sideburn', 'short'],
  };
  return map[id] ?? [];
}

/**
 * 用正式预设表填充 RecruitLibrary。配置非法时抛错，不静默跳过。
 */
export function libraryFromPresets(gender: Gender, compat?: HeadCompat, file: FacePresetsFile = DEFAULT_FACE_PRESETS): RecruitLibrary {
  if (compat) {
    const val = validateFacePresets(file, compat);
    if (!val.ok) {
      const codes = val.issues.map((i) => i.code).join(',');
      throw new Error(`face_presets_v1 加载失败：${codes}；${val.issues[0]?.message ?? ''}`);
    }
  }
  const beards: BeardEntry[] =
    gender === 'm'
      ? ['bd_01', 'bd_02', 'bd_03', 'bd_04', 'bd_05'].map((id) => ({
          id,
          tags: compat ? tagsOf(compat, id) : defaultBeardTags(id),
        }))
      : [];
  return {
    faces: { youth: ['fc_01', 'fc_03'], mature: ['fc_02'] },
    eyes: ['ey_01', 'ey_03'],
    brows: ['br_01'],
    mouths: ['mo_01', 'mo_03'],
    noses: ['no_01', 'no_02', 'no_03', 'no_04', 'no_05'],
    beards,
    hairs: gender === 'm' ? ['hr_01', 'hr_04', 'hr_05'] : ['hr_02', 'hr_04', 'hr_05'],
    marks: ['ag_01'],
    presets: recipesToLibrary(file, gender, compat),
  };
}

/** 创角：五官 + init 发型/肤色/发色作为初值。 */
export function lookFromCreatePreset(
  gender: Gender,
  presetId: string,
  file: FacePresetsFile = DEFAULT_FACE_PRESETS,
  extras: Partial<LookV3> = {},
): LookV3 {
  const hit = findPreset(gender, presetId, file);
  if (!hit) throw new Error(`未知预设 ${gender}/${presetId}`);
  const { rec, ageBand } = hit;
  return {
    schema: LOOK_SCHEMA,
    libVersion: extras.libVersion ?? LIB_VERSION,
    gender,
    ageBand,
    preset: rec.id,
    face: rec.face,
    eyes: rec.eyes,
    brow: rec.brow,
    mouth: rec.mouth,
    nose: rec.nose,
    beard: gender === 'm' ? rec.beard : null,
    skinTone: rec.init.skinTone,
    mark: rec.mark,
    hair: rec.init.hair,
    hairColor: rec.init.hairColor,
    bodyType: extras.bodyType ?? 'A',
    appearanceSeed: extras.appearanceSeed ?? 0,
    locked: extras.locked ?? false,
  };
}

/** T1：与策划表逐格比对用的静态期望（不含 init 以外的招募随机项）。 */
export function expectedRecipeGrid(): Record<Gender, Record<OfficialPresetId, Omit<FacePresetRecipe, 'init'> & { ageBand: AgeBand; init: PresetInit }>> {
  const file = DEFAULT_FACE_PRESETS;
  const out = { m: {}, f: {} } as Record<Gender, Record<OfficialPresetId, Omit<FacePresetRecipe, 'init'> & { ageBand: AgeBand; init: PresetInit }>>;
  for (const gender of ['m', 'f'] as const) {
    for (const { ageBand, rec } of bandsOf(file, gender)) {
      out[gender][rec.id as OfficialPresetId] = { ...rec, ageBand, init: rec.init };
    }
  }
  return out;
}
