/**
 * 五官扩充加载框架入口。
 * 在 4184 加载框架上做 P1 合并校验；渲染与契约在同目录其它模块。不改现行 bones。
 */
import {
  BATCH_EXPAND_E1,
  isFaceRedrawMounted,
  LOAD_ORDER_WITH_FACE_REDRAW,
} from './config/batches_MT';
import { EXPECTED_SHA256 } from './config/expectedSha_MT';
import {
  buildEffectiveEntries,
  indexLegacyIds,
  peekPremergedSocketSet,
  resolvePartRef,
  type ResolveContext,
  type ResolveResult,
} from './resolve_MT';
import { collectExistingIds, validateExpandPackage, validateOutfit, validateSocketSetTables } from './validate_MT';
import {
  LOADER_VERSION,
  type ExpandManifest,
  type HeadCompat,
  type LegacyIdCatalog,
  type PartRef,
  type ValidationResult,
} from './types_MT';

export { HOOK_NAME, LOADER_VERSION, PREV_VERSION } from './types_MT';
export { peekPremergedSocketSet, resolvePartRef, buildEffectiveEntries };

export interface LoaderInput {
  manifest: ExpandManifest;
  compat: HeadCompat;
  legacyIds: LegacyIdCatalog;
  loadOrder: readonly string[];
  /** 若传入则覆盖默认（W2+ne+face_redraw 已交 id 全集）。 */
  existingIds?: Iterable<string>;
}

export class LibExpandLoader {
  readonly version = LOADER_VERSION;
  readonly loadOrder: readonly string[];
  readonly faceRedrawMounted: boolean;
  readonly existingIds: Set<string>;
  readonly ctx: ResolveContext;
  readonly manifest: ExpandManifest;
  readonly compat: HeadCompat;

  constructor(input: LoaderInput) {
    this.manifest = input.manifest;
    this.compat = input.compat;
    this.loadOrder = [...input.loadOrder];
    this.faceRedrawMounted = isFaceRedrawMounted(this.loadOrder);
    this.existingIds = input.existingIds
      ? new Set(input.existingIds)
      : collectExistingIds(input.legacyIds);
    const effective = buildEffectiveEntries(input.compat, this.loadOrder);
    this.ctx = {
      compat: input.compat,
      loadOrder: this.loadOrder,
      effective,
      legacyById: indexLegacyIds(input.legacyIds),
    };
  }

  /** 包级：append 冲突、扩库 id 必须出现在 byId、socket 对照表。 */
  validatePackage(): ValidationResult {
    const pkg = validateExpandPackage(this.manifest, this.compat, this.existingIds);
    const table = validateSocketSetTables(this.compat);
    return {
      ok: pkg.ok && table.ok,
      issues: [...pkg.issues, ...table.issues],
      resolved: [],
    };
  }

  resolve(ref: PartRef): ResolveResult {
    return resolvePartRef(ref, this.ctx);
  }

  validateOutfit(refs: readonly PartRef[]): ValidationResult {
    return validateOutfit(refs, this.ctx);
  }

  /** 对照用：预合并表中的 socketSet。解析路径不会走这里。 */
  premergedSocketSet(gender: 'f' | 'm', partSet: string): string | undefined {
    return peekPremergedSocketSet(this.compat, gender, partSet);
  }

  summary() {
    return {
      version: this.version,
      loadOrder: [...this.loadOrder],
      faceRedrawMounted: this.faceRedrawMounted,
      effectiveEntryCount: this.ctx.effective.length,
      expandPartCount: this.manifest.parts.length,
      byIdCount: Object.keys(this.compat.byId).length,
      usedPremergedByGenderPartSet: false,
    };
  }
}

export function createLoader(input: LoaderInput): LibExpandLoader {
  return new LibExpandLoader(input);
}

export const DEFAULT_E1_LOAD_ORDER = LOAD_ORDER_WITH_FACE_REDRAW;
export const DEFAULT_EXPAND_BATCH = BATCH_EXPAND_E1;
export const SHA = EXPECTED_SHA256;
