/**
 * 按「实际加载批次」从 entries.sourceBatch 解析生效件与 socketSet。
 * 故意不把 byGenderPartSet 当作解析源：那是假设完整 loadOrder 的预合并视图。
 */
import { loadOrderRank } from './config/batches_MT';
import type {
  CompatEntry,
  Gender,
  HeadCompat,
  LegacyIdCatalog,
  LegacyIdRecord,
  LookupKind,
  PartRef,
  ResolvedPart,
} from './types_MT';

const ID_RE = /^part_([fm])_head_([a-z]{2}_\d{2})_/;

export function parseId(id: string): { gender: Gender; partSet: string } | null {
  const m = ID_RE.exec(id);
  if (!m) return null;
  return { gender: m[1] as Gender, partSet: m[2]! };
}

export function indexLegacyIds(catalog: LegacyIdCatalog): Map<string, LegacyIdRecord> {
  const map = new Map<string, LegacyIdRecord>();
  for (const rec of catalog.ids) map.set(rec.id, rec);
  return map;
}

/**
 * 从 entries 按本次 loadOrder 合成生效表：同一 (gender, partSet) 只保留秩最高的批次，
 * 同一批次多行（发型后片+前片）全部保留。未挂入的 sourceBatch 直接丢掉。
 */
export function buildEffectiveEntries(
  compat: HeadCompat,
  loadOrder: readonly string[],
): CompatEntry[] {
  const chosen = new Map<string, { rank: number; rows: CompatEntry[] }>();
  for (const entry of compat.entries) {
    const rank = loadOrderRank(entry.sourceBatch, loadOrder);
    if (rank < 0) continue;
    const key = `${entry.gender}::${entry.partSet}`;
    const prev = chosen.get(key);
    if (!prev || rank > prev.rank) {
      chosen.set(key, { rank, rows: [entry] });
    } else if (rank === prev.rank) {
      prev.rows.push(entry);
    }
  }
  const out: CompatEntry[] = [];
  for (const { rows } of chosen.values()) out.push(...rows);
  return out;
}

export function entriesForPartSet(
  effective: readonly CompatEntry[],
  gender: Gender,
  partSet: string,
): CompatEntry[] {
  return effective.filter((e) => e.gender === gender && e.partSet === partSet);
}

export function toResolved(entry: CompatEntry, lookup: LookupKind, byIdHit: boolean, id?: string): ResolvedPart {
  return {
    gender: entry.gender,
    partSet: entry.partSet,
    sourceBatch: entry.sourceBatch,
    socketSet: entry.socketSet,
    category: entry.category,
    id: id ?? entry.id,
    noseBaked: entry.noseBaked,
    lookup,
    byIdHit,
  };
}

export interface ResolveContext {
  compat: HeadCompat;
  loadOrder: readonly string[];
  effective: readonly CompatEntry[];
  legacyById: Map<string, LegacyIdRecord>;
}

export interface ResolveOk {
  ok: true;
  resolved: ResolvedPart[];
  /** 旧 id 不在 byId 中，但已按 entries 查到——这是预期，不是失败。 */
  byIdMissingButResolvedViaEntries: boolean;
}

export interface ResolveErr {
  ok: false;
  issues: { code: string; message: string; detail?: unknown }[];
}

export type ResolveResult = ResolveOk | ResolveErr;

export function resolvePartRef(ref: PartRef, ctx: ResolveContext): ResolveResult {
  const { compat, loadOrder, effective, legacyById } = ctx;

  if (ref.id) {
    const byIdRow = compat.byId[ref.id];
    if (byIdRow) {
      const rank = loadOrderRank(byIdRow.sourceBatch, loadOrder);
      if (rank < 0) {
        return {
          ok: false,
          issues: [
            {
              code: 'EXPAND_ID_BATCH_NOT_MOUNTED',
              message: `byId 命中 ${ref.id}，但其 sourceBatch ${byIdRow.sourceBatch} 不在本次 loadOrder`,
              detail: { id: ref.id, sourceBatch: byIdRow.sourceBatch, loadOrder: [...loadOrder] },
            },
          ],
        };
      }
      if (byIdRow.gender !== ref.gender || byIdRow.partSet !== ref.partSet) {
        return {
          ok: false,
          issues: [
            {
              code: 'BYID_REF_MISMATCH',
              message: `byId[${ref.id}] 的 (gender, partSet) 与查询不一致`,
              detail: { ref, byId: { gender: byIdRow.gender, partSet: byIdRow.partSet } },
            },
          ],
        };
      }
      return { ok: true, resolved: [toResolved(byIdRow, 'byId', true, ref.id)], byIdMissingButResolvedViaEntries: false };
    }

    // byId 未覆盖：旧件按 (gender, partSet) 和 entries 查，不视为失败。
    const legacy = legacyById.get(ref.id);
    const parsed = parseId(ref.id);
    const gender = ref.gender ?? legacy?.gender ?? parsed?.gender;
    const partSet = ref.partSet ?? legacy?.partSet ?? parsed?.partSet;
    if (!gender || !partSet) {
      return {
        ok: false,
        issues: [
          {
            code: 'UNKNOWN_ID',
            message: `无法解析 id ${ref.id}，且不在 byId / 旧件目录中`,
            detail: { id: ref.id },
          },
        ],
      };
    }
    if (gender !== ref.gender || partSet !== ref.partSet) {
      return {
        ok: false,
        issues: [
          {
            code: 'ID_PART_MISMATCH',
            message: `id ${ref.id} 推得 (${gender}, ${partSet}) 与查询 (${ref.gender}, ${ref.partSet}) 不一致`,
          },
        ],
      };
    }
    const rows = entriesForPartSet(effective, gender, partSet);
    if (rows.length === 0) {
      return {
        ok: false,
        issues: [
          {
            code: 'ENTRY_NOT_FOUND',
            message: `旧件 ${ref.id} 不在 byId（预期），但本次 loadOrder 的 entries 也没有 (${gender}, ${partSet})`,
            detail: { ref, loadOrder: [...loadOrder] },
          },
        ],
      };
    }
    return {
      ok: true,
      resolved: rows.map((row) => toResolved(row, 'parsedId+entries', false, ref.id)),
      byIdMissingButResolvedViaEntries: true,
    };
  }

  const rows = entriesForPartSet(effective, ref.gender, ref.partSet);
  if (rows.length === 0) {
    return {
      ok: false,
      issues: [
        {
          code: 'ENTRY_NOT_FOUND',
          message: `按 (gender=${ref.gender}, partSet=${ref.partSet}) 在本次 entries 中未找到`,
          detail: { ref, loadOrder: [...loadOrder] },
        },
      ],
    };
  }
  const resolved = rows.map((row) => {
    const hit = !!(row.id && compat.byId[row.id]);
    return toResolved(row, 'entries', hit, row.id);
  });
  return { ok: true, resolved, byIdMissingButResolvedViaEntries: false };
}

/**
 * 预合并表只用于对照，证明「未挂 face_redraw 时没有误采」。
 * 解析路径不得调用本函数。
 */
export function peekPremergedSocketSet(
  compat: HeadCompat,
  gender: Gender,
  partSet: string,
): string | undefined {
  return compat.byGenderPartSet[gender]?.[partSet]?.socketSet;
}
