/**
 * 包级校验（append / byId 覆盖）与同一角色 socketSet 一致性校验。
 * 不挂图、不改 bones、不做 P1–P6 存档 / 创角逻辑。
 */
import { derivedNose, EXPECTED_NOSE, SOCKET_SETS } from './config/socketSets_MT';
import type {
  ExpandManifest,
  Gender,
  HeadCompat,
  Issue,
  LegacyIdCatalog,
  PartRef,
  SocketSetName,
  ValidationResult,
} from './types_MT';
import { resolvePartRef, type ResolveContext } from './resolve_MT';

const EPS = 1e-4;

export function close(a: number, b: number, eps = EPS): boolean {
  return Math.abs(a - b) <= eps;
}

export function collectExistingIds(catalog: LegacyIdCatalog): Set<string> {
  return new Set(catalog.ids.map((r) => r.id));
}

/** 头兼容表缺任一扩库 id → 失败，不默认填。byId 只覆盖本包 29 条是预期。 */
export function validateExpandPackage(
  manifest: ExpandManifest,
  compat: HeadCompat,
  existingIds: ReadonlySet<string>,
): ValidationResult {
  const issues: Issue[] = [];

  if (manifest.patchMode !== 'append') {
    issues.push({
      code: 'PATCH_MODE',
      message: `扩充包 patchMode 必须为 append，实际为 ${JSON.stringify(manifest.patchMode)}`,
    });
  }

  const parts = manifest.parts ?? [];
  const seen = new Set<string>();
  for (const part of parts) {
    if (!part.id) {
      issues.push({ code: 'PART_MISSING_ID', message: `清单条目缺少 id：${part.gender}/${part.partSet}` });
      continue;
    }
    if (seen.has(part.id)) {
      issues.push({ code: 'DUP_ID_IN_MANIFEST', message: `清单内部 id 重复：${part.id}` });
    }
    seen.add(part.id);
    if (existingIds.has(part.id)) {
      issues.push({
        code: 'APPEND_ID_CONFLICT',
        message: `patchMode:append 与已有 id 冲突：${part.id}`,
        detail: { id: part.id, gender: part.gender, partSet: part.partSet },
      });
    }
    if (!compat.byId[part.id]) {
      issues.push({
        code: 'COMPAT_MISSING_EXPAND_ID',
        message: `head_compat 缺扩库 id：${part.id}，不得默认填`,
        detail: { id: part.id },
      });
    }
  }

  const byIdKeys = Object.keys(compat.byId);
  for (const id of byIdKeys) {
    if (!seen.has(id)) {
      // byId 多出的键不是本包清单 id：按口径 byId 应覆盖本包 29 条；多出也不当成功默认。给出警告级错误。
      issues.push({
        code: 'BYID_UNKNOWN_KEY',
        message: `byId 含清单外 id：${id}`,
      });
    }
  }

  if (compat.expansionIdCount != null && compat.expansionIdCount !== parts.length) {
    issues.push({
      code: 'EXPANSION_COUNT',
      message: `expansionIdCount=${compat.expansionIdCount} 与清单条数 ${parts.length} 不一致`,
    });
  }

  return { ok: issues.length === 0, issues, resolved: [] };
}

export function validateOutfit(refs: readonly PartRef[], ctx: ResolveContext): ValidationResult {
  const issues: Issue[] = [];
  const resolved = [];
  for (const ref of refs) {
    const result = resolvePartRef(ref, ctx);
    if (!result.ok) {
      issues.push(...result.issues);
      continue;
    }
    resolved.push(...result.resolved);
  }
  const sets = new Set(resolved.map((r) => r.socketSet));
  if (sets.size > 1) {
    issues.push({
      code: 'MIXED_SOCKET_SET',
      message: `同一角色只允许同一 socketSet，不得混挂 w2_legacy 与 redraw_1110。当前：${[...sets].join(' + ')}`,
      detail: resolved.map((r) => ({
        gender: r.gender,
        partSet: r.partSet,
        id: r.id,
        sourceBatch: r.sourceBatch,
        socketSet: r.socketSet,
      })),
    });
  }
  return { ok: issues.length === 0, issues, resolved };
}

export function validateSocketSetTables(compat: HeadCompat): ValidationResult {
  const issues: Issue[] = [];
  const genders: Gender[] = ['f', 'm'];
  const names: SocketSetName[] = ['w2_legacy', 'redraw_1110'];
  for (const name of names) {
    for (const g of genders) {
      const expected = SOCKET_SETS[name][g];
      const got = compat.socketSets[name]?.[g];
      if (!got) {
        issues.push({ code: 'SOCKET_TABLE_MISSING', message: `compat.socketSets.${name}.${g} 缺失` });
        continue;
      }
      for (const key of ['eye_l', 'eye_r', 'mouth'] as const) {
        const ev = expected[key];
        const gv = got[key];
        if (!gv || gv.length < 2 || !close(gv[0]!, ev[0]) || !close(gv[1]!, ev[1])) {
          issues.push({
            code: 'SOCKET_TABLE_MISMATCH',
            message: `compat.socketSets.${name}.${g}.${key} 与口径不符`,
            detail: { expected: ev, got: gv },
          });
        }
      }
    }
  }
  for (const g of genders) {
    const n = derivedNose('redraw_1110', g);
    const exp = EXPECTED_NOSE[g];
    if (!close(n[0], exp[0], 0.01) || !close(n[1], exp[1], 0.01)) {
      issues.push({
        code: 'NOSE_FORMULA',
        message: `派生鼻点 ${g} 与口径 ${exp.join(',')} 不符，算得 ${n.join(',')}`,
      });
    }
    const got = compat.socketSets.redraw_1110?.[g]?.nose;
    if (got && (!close(got[0]!, exp[0], 0.01) || !close(got[1]!, exp[1], 0.01))) {
      issues.push({
        code: 'NOSE_TABLE_MISMATCH',
        message: `compat 鼻点 ${g} 与口径不符`,
        detail: { expected: exp, got },
      });
    }
  }
  return { ok: issues.length === 0, issues, resolved: [] };
}
