/**
 * P5 招募随机：在分件库 §6.2 顺序上按方案 §2.9 / §2.10 补鼻与胡须；libVersion +1。
 * 种子公式不改：appearanceSeed = hash(seed, "look", libVersion)；PRNG 为 mulberry32。
 */
import { LIB_VERSION, type AgeBand, type LookV3 } from './appearance_MT';
import { OFFICIAL_HAIR_IDS, SKIN_IDS } from './palette_MT';
import type { Gender, HeadCompat } from './types_MT';
import { libraryFromPresets } from './presets_MT';
import { assertGeneratedAppearance } from './lookValidate_MT';

/** 招募发色池（V10）：官方色板定稿前只含 hc_01–06，不含 hc_07–10。 */
export const RECRUIT_HAIR_COLOR_IDS = OFFICIAL_HAIR_IDS;

export const PRESET_RATE = 0.6;
export const YOUTH_RATE = 0.7;
export const YOUTH_BEARD_RATE = 0.3;
export const MATURE_BEARD_RATE = 0.55;
export const FEMALE_BEARD_RATE = 0;

export type StreamType = 'sing' | 'dance' | 'chat' | 'sell' | 'game' | 'skill';

export interface BeardEntry {
  id: string;
  tags: string[];
}

export interface RecruitLibrary {
  faces: Record<AgeBand, string[]>;
  eyes: string[];
  brows: string[];
  mouths: string[];
  noses: string[];
  beards: BeardEntry[];
  hairs: string[];
  marks: string[];
  presets: Record<AgeBand, LookRecipe[]>;
}

export interface LookInit {
  hair: string;
  skinTone: string;
  hairColor: string;
}

export interface LookRecipe {
  id: string;
  face: string;
  eyes: string;
  brow: string;
  mouth: string;
  nose: string | null;
  beard: string | null;
  mark: string | null;
  /** 只作创角初值；招募不读。 */
  init?: LookInit;
}

export function mulberry32(a: number) {
  return () => {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** appearanceSeed = hash(recruitSeed, "look", libVersion) */
export function hashLookSeed(recruitSeed: number, libVersion: number = LIB_VERSION): number {
  const s = `${recruitSeed}|look|${libVersion}`;
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function pick<T>(rnd: () => number, arr: readonly T[]): T {
  if (arr.length === 0) throw new Error('empty pick');
  return arr[Math.floor(rnd() * arr.length) % arr.length]!;
}


export function defaultRecruitLibrary(gender: Gender, compat?: HeadCompat): RecruitLibrary {
  return libraryFromPresets(gender, compat);
}


export function isYouthBeardEligible(tags: readonly string[]): boolean {
  return tags.includes('stubble') || tags.includes('short');
}

export function isNoseBakedFace(face: string): boolean {
  return face === 'fc_01' || face === 'fc_02';
}

/**
 * 胡须抽取（男）。青年只从 stubble/short 池抽；池为空则不长胡须且不报错。
 * 女不抽。熟龄全款可抽。
 */
export function rollBeard(
  rnd: () => number,
  gender: Gender,
  ageBand: AgeBand,
  beards: readonly BeardEntry[],
): { beard: string | null; poolEmpty: boolean; rolled: boolean } {
  if (gender !== 'm') return { beard: null, poolEmpty: false, rolled: false };
  const rate = ageBand === 'youth' ? YOUTH_BEARD_RATE : MATURE_BEARD_RATE;
  const pool =
    ageBand === 'youth' ? beards.filter((b) => isYouthBeardEligible(b.tags)) : [...beards];
  if (pool.length === 0) return { beard: null, poolEmpty: true, rolled: false };
  const has = rnd() < rate;
  if (!has) return { beard: null, poolEmpty: false, rolled: true };
  return { beard: pick(rnd, pool).id, poolEmpty: false, rolled: true };
}

export interface RecruitInput {
  recruitSeed: number;
  gender?: Gender;
  ageBand?: AgeBand;
  type?: StreamType;
  libVersion?: number;
  lib?: RecruitLibrary;
  /** 若给定则跳过 60/40 预设判定，强制走该支路（自测用）。 */
  forceBranch?: 'preset' | 'tune';
  /** 用于生成后内部断言（四条约束）。不向客户端返 422。 */
  compat?: HeadCompat;
}

export interface RecruitResult {
  look: LookV3;
  appearanceSeed: number;
  branch: 'preset' | 'tune';
  type: StreamType;
  beardMeta: { poolEmpty: boolean; rolled: boolean };
}

const TYPES: StreamType[] = ['sing', 'dance', 'chat', 'sell', 'game', 'skill'];

/**
 * 顺序（§2.9 叠在分件库 §6.2 上）：
 * 类型 → 性别 → 年龄段 → 预设脸(60%) 或 随机微调(40%)
 *   预设：配方自带 nose / beard
 *   微调：脸型 → 眼 → 眉 → 嘴 → 鼻 → 年龄细节 → 胡须(男)
 * → 肤色 → 发型 + 发色 →（服装/饰品本预览不加，跳过）→ 禁止表
 */
export function recruitLook(input: RecruitInput): RecruitResult {
  const libVersion = input.libVersion ?? LIB_VERSION;
  const appearanceSeed = hashLookSeed(input.recruitSeed, libVersion);
  const rnd = mulberry32(appearanceSeed);
  const type = input.type ?? pick(rnd, TYPES);
  const gender: Gender = input.gender ?? (rnd() < 0.5 ? 'f' : 'm');
  const ageBand: AgeBand = input.ageBand ?? (rnd() < YOUTH_RATE ? 'youth' : 'mature');
  const lib = input.lib ?? defaultRecruitLibrary(gender);
  const branch: 'preset' | 'tune' = input.forceBranch ?? (rnd() < PRESET_RATE ? 'preset' : 'tune');

  let face: string;
  let eyes: string;
  let brow: string;
  let mouth: string;
  let nose: string | null;
  let beard: string | null;
  let mark: string | null;
  let preset: string | null = null;
  let beardMeta = { poolEmpty: false, rolled: false };

  if (branch === 'preset' && lib.presets[ageBand].length > 0) {
    const rec = pick(rnd, lib.presets[ageBand]);
    preset = rec.id;
    face = rec.face;
    eyes = rec.eyes;
    brow = rec.brow;
    mouth = rec.mouth;
    nose = rec.nose;
    beard = gender === 'm' ? rec.beard : null;
    mark = rec.mark;
  } else {
    face = pick(rnd, lib.faces[ageBand].length ? lib.faces[ageBand] : lib.faces.youth);
    eyes = pick(rnd, lib.eyes);
    brow = pick(rnd, lib.brows);
    mouth = pick(rnd, lib.mouths);
    if (isNoseBakedFace(face)) nose = null;
    else nose = pick(rnd, lib.noses);
    mark = ageBand === 'mature' ? pick(rnd, [...lib.marks]) : rnd() < 0.15 ? pick(rnd, lib.marks) : null;
    const rolled = rollBeard(rnd, gender, ageBand, lib.beards);
    beard = rolled.beard;
    beardMeta = { poolEmpty: rolled.poolEmpty, rolled: rolled.rolled };
  }

  // 禁止表 §2.10（本预览范围）
  if (gender !== 'm') beard = null;
  if (isNoseBakedFace(face)) nose = null;

  const skinTone = pick(rnd, SKIN_IDS);
  const hair = pick(rnd, lib.hairs);
  const hairColor = pick(rnd, RECRUIT_HAIR_COLOR_IDS);

  const look: LookV3 = {
    schema: 'v1.appearance.proposed.3',
    libVersion,
    gender,
    ageBand,
    preset,
    face,
    eyes,
    brow,
    mouth,
    nose,
    beard,
    skinTone,
    mark,
    hair,
    hairColor,
    bodyType: 'A',
    appearanceSeed,
    locked: true,
  };
  // 四条约束：生成器内部断言拦住，不返 422、不重随。
  assertGeneratedAppearance(look, input.compat);
  return { look, appearanceSeed, branch: preset ? 'preset' : 'tune', type, beardMeta };
}

export interface BeardRateReport {
  n: number;
  youthMale: { n: number; bearded: number; rate: number };
  matureMale: { n: number; bearded: number; rate: number };
  female: { n: number; bearded: number; rate: number };
  sameSeedRepeats: boolean;
}

export function measureBeardRates(
  seeds: number[],
  opts: { forceGender?: Gender; forceAge?: AgeBand; forceBranch?: 'preset' | 'tune'; lib?: RecruitLibrary; compat?: HeadCompat } = {},
): BeardRateReport {
  const youthMale = { n: 0, bearded: 0, rate: 0 };
  const matureMale = { n: 0, bearded: 0, rate: 0 };
  const female = { n: 0, bearded: 0, rate: 0 };
  let sameSeedRepeats = true;
  for (const seed of seeds) {
    const a = recruitLook({
      recruitSeed: seed,
      gender: opts.forceGender,
      ageBand: opts.forceAge,
      forceBranch: opts.forceBranch,
      lib: opts.lib,
      compat: opts.compat,
    });
    const b = recruitLook({
      recruitSeed: seed,
      gender: opts.forceGender,
      ageBand: opts.forceAge,
      forceBranch: opts.forceBranch,
      lib: opts.lib,
      compat: opts.compat,
    });
    if (JSON.stringify(a.look) !== JSON.stringify(b.look)) sameSeedRepeats = false;
    if (a.look.gender === 'f') {
      female.n += 1;
      if (a.look.beard) female.bearded += 1;
    } else if (a.look.ageBand === 'youth') {
      youthMale.n += 1;
      if (a.look.beard) youthMale.bearded += 1;
    } else {
      matureMale.n += 1;
      if (a.look.beard) matureMale.bearded += 1;
    }
  }
  youthMale.rate = youthMale.n ? youthMale.bearded / youthMale.n : 0;
  matureMale.rate = matureMale.n ? matureMale.bearded / matureMale.n : 0;
  female.rate = female.n ? female.bearded / female.n : 0;
  return { n: seeds.length, youthMale, matureMale, female, sameSeedRepeats };
}

export interface PresetHitReport {
  n: number;
  hits: Record<string, number>;
  rates: Record<string, number>;
  beardRate: number;
  bearded: number;
}

/** T5：固定走预设支路，统计各 pf 命中率与胡须率。 */
export function measurePresetHits(
  seeds: number[],
  opts: { gender: Gender; ageBand: AgeBand; lib?: RecruitLibrary; compat?: HeadCompat },
): PresetHitReport {
  const hits: Record<string, number> = {};
  let bearded = 0;
  for (const seed of seeds) {
    const r = recruitLook({
      recruitSeed: seed,
      gender: opts.gender,
      ageBand: opts.ageBand,
      forceBranch: 'preset',
      lib: opts.lib,
      compat: opts.compat,
    });
    const id = r.look.preset ?? '(null)';
    hits[id] = (hits[id] ?? 0) + 1;
    if (r.look.beard) bearded += 1;
  }
  const rates: Record<string, number> = {};
  for (const [id, n] of Object.entries(hits)) rates[id] = n / seeds.length;
  return { n: seeds.length, hits, rates, beardRate: bearded / seeds.length, bearded };
}
