/**
 * P6 服务器校验（本地纯函数 + 单测，不部署）。
 * 契约定稿 §5.13 七条约束：profile/look 违反一律 422；生成外观走内部断言，不返 422、不重随。
 * 读旧档不走本校验、不重随。
 */
import { isNoseBaked, type LookV3 } from './appearance_MT';
import type { Gender, HeadCompat, Issue } from './types_MT';
import { OFFICIAL_HAIR_IDS } from './palette_MT';

/** 官方 10 档色板定稿前的开放发色池：hc_01–06。hc_07–10 及不存在的 id 一律拒。 */
export const OPEN_HAIR_COLOR_IDS = OFFICIAL_HAIR_IDS;
const OPEN_HAIR_COLOR_SET = new Set<string>(OFFICIAL_HAIR_IDS);

export interface LookSubmit {
  gender: Gender;
  face: string;
  eyes?: string;
  brow?: string;
  mouth?: string;
  nose?: string | null;
  beard?: string | null;
  skinTone?: string;
  mark?: string | null;
  hair?: string;
  hairColor?: string;
}

export interface ValidateLookResult {
  ok: boolean;
  status: 200 | 422;
  issues: Issue[];
}

export interface LookCatalog {
  noses: ReadonlySet<string>;
  beards: ReadonlySet<string>;
  faces: ReadonlySet<string>;
  brows: ReadonlySet<string>;
}

export function catalogFromCompat(compat: HeadCompat, gender: Gender): LookCatalog {
  const noses = new Set<string>();
  const beards = new Set<string>();
  const faces = new Set<string>();
  const brows = new Set<string>();
  for (const e of compat.entries ?? []) {
    if (e.category === 'face_shape' || e.partSet.startsWith('fc_')) {
      if (e.gender === gender) faces.add(e.partSet);
    }
    if (e.category === 'nose' || e.partSet.startsWith('no_')) {
      if (e.gender === gender) noses.add(e.partSet);
    }
    if (e.category === 'brow' || e.partSet.startsWith('br_')) {
      if (e.gender === gender) brows.add(e.partSet);
    }
    if (e.category === 'beard' || e.partSet.startsWith('bd_')) {
      beards.add(e.partSet);
    }
  }
  const table = compat.byGenderPartSet?.[gender] ?? {};
  for (const [partSet, row] of Object.entries(table)) {
    if (row.category === 'brow' || partSet.startsWith('br_')) brows.add(partSet);
    if (row.category === 'face_shape' || partSet.startsWith('fc_')) faces.add(partSet);
    if (row.category === 'nose' || partSet.startsWith('no_')) noses.add(partSet);
    if (row.category === 'beard' || partSet.startsWith('bd_')) beards.add(partSet);
  }
  for (const [id, row] of Object.entries(compat.byId ?? {})) {
    if (row.category === 'beard' || row.partSet.startsWith('bd_')) beards.add(row.partSet);
    if ((row.category === 'nose' || row.partSet.startsWith('no_')) && row.gender === gender) {
      noses.add(row.partSet);
    }
    if ((row.category === 'face_shape' || row.partSet.startsWith('fc_')) && row.gender === gender) {
      faces.add(row.partSet);
    }
    if ((row.category === 'brow' || row.partSet.startsWith('br_')) && row.gender === gender) {
      brows.add(row.partSet);
    }
    void id;
  }
  return { noses, beards, faces, brows };
}

export function socketSetOf(compat: HeadCompat, gender: Gender, partSet: string): string | undefined {
  const row = compat.byGenderPartSet?.[gender]?.[partSet];
  if (row?.socketSet) return row.socketSet;
  const hit = (compat.entries ?? []).find((e) => e.gender === gender && e.partSet === partSet && e.socketSet);
  return hit?.socketSet;
}

function issue(code: string, message: string, detail?: unknown): Issue {
  return detail !== undefined ? { code, message, detail } : { code, message };
}

/**
 * 七条约束的共同收集。不返回 HTTP 状态。
 * 缺字段按「未提交」而不是偷偷补写；hairColor 仅在提交了该字段（或 requireHairColor）时检查。
 */
export function collectLookConstraintIssues(
  submit: LookSubmit,
  compat: HeadCompat,
  opts: { requireHairColor?: boolean; catalog?: LookCatalog } = {},
): Issue[] {
  const issues: Issue[] = [];
  const cat = opts.catalog ?? catalogFromCompat(compat, submit.gender);
  const baked = isNoseBaked(compat, submit.gender, submit.face);

  // 1. beard_invalid：女非 null，或 id 不在本性别库（男库）
  if (submit.beard != null) {
    if (submit.gender !== 'm' || !cat.beards.has(submit.beard)) {
      issues.push(
        issue('beard_invalid', 'beard 只收本性别库（男库）id；女角色必须为 null', { beard: submit.beard, gender: submit.gender }),
      );
    }
  }

  const noseSubmitted = Object.prototype.hasOwnProperty.call(submit, 'nose');
  // 2. nose_baked_conflict
  if (baked && submit.nose != null) {
    issues.push(
      issue('nose_baked_conflict', 'nose 不得与 noseBaked:true 的脸型同存', {
        face: submit.face,
        nose: submit.nose,
      }),
    );
  }
  // 3. nose_required
  if (!baked && (submit.nose == null || !noseSubmitted)) {
    issues.push(
      issue('nose_required', 'noseBaked:false 时 nose 不能为 null（缺字段或显式 null 均 422 nose_required）', {
        face: submit.face,
        nose: noseSubmitted ? submit.nose : undefined,
        fieldPresent: noseSubmitted,
      }),
    );
  }
  // 4. brow_invalid
  const brow = submit.brow;
  if (brow == null || brow === '' || !cat.brows.has(brow)) {
    issues.push(
      issue('brow_invalid', 'brow 必须非空且属于该性别库', {
        brow: brow ?? null,
        fieldPresent: Object.prototype.hasOwnProperty.call(submit, 'brow'),
      }),
    );
  }
  // 5. hair_color_invalid：色池以外（含 hc_07–10 和不存在的 id）一律拒
  const hairColorSubmitted = Object.prototype.hasOwnProperty.call(submit, 'hairColor');
  if (hairColorSubmitted || opts.requireHairColor) {
    const hc = submit.hairColor;
    if (!hc || !OPEN_HAIR_COLOR_SET.has(hc)) {
      issues.push(
        issue('hair_color_invalid', 'hairColor 只收当前开放色池 hc_01–06；hc_07–10 及不存在的 id 一律拒', {
          hairColor: hc ?? null,
          pool: [...OPEN_HAIR_COLOR_IDS],
        }),
      );
    }
  }
  // 6. nose_invalid：nose 非空但不在本性别库（废弃 NOSE_UNKNOWN）
  if (submit.nose != null && !cat.noses.has(submit.nose)) {
    issues.push(issue('nose_invalid', `鼻件 ${submit.nose} 不在该性别库`, { nose: submit.nose }));
  }

  // 7. socket_mixed：已提交且能查到插槽的五官件必须同一套
  const featureKeys: { key: 'face' | 'eyes' | 'brow' | 'mouth' | 'nose' | 'beard' | 'mark'; id: string | null | undefined; gender: Gender }[] = [
    { key: 'face', id: submit.face, gender: submit.gender },
    { key: 'eyes', id: submit.eyes, gender: submit.gender },
    { key: 'brow', id: submit.brow, gender: submit.gender },
    { key: 'mouth', id: submit.mouth, gender: submit.gender },
    { key: 'nose', id: submit.nose, gender: submit.gender },
    { key: 'beard', id: submit.beard, gender: 'm' },
    { key: 'mark', id: submit.mark, gender: submit.gender },
  ];
  const sockets: { key: string; id: string; socketSet: string }[] = [];
  for (const f of featureKeys) {
    if (f.id == null || f.id === '') continue;
    const ss = socketSetOf(compat, f.gender, f.id);
    if (ss) sockets.push({ key: f.key, id: f.id, socketSet: ss });
  }
  const unique = [...new Set(sockets.map((s) => s.socketSet))];
  if (unique.length > 1) {
    issues.push(
      issue('socket_mixed', '同一角色的五官件必须来自同一套插槽', {
        sockets,
        sets: unique,
      }),
    );
  }

  return issues;
}

/**
 * PUT profile/look：违反七条约束一律 422。
 */
export function validateLookSubmit(
  submit: LookSubmit,
  compat: HeadCompat,
  catalog?: LookCatalog,
): ValidateLookResult {
  const issues = collectLookConstraintIssues(submit, compat, { catalog });
  return { ok: issues.length === 0, status: issues.length === 0 ? 200 : 422, issues };
}

/** 仅用于已通过规范化的完整 look 做生成/招募校验，不用于读旧档。 */
export function validateStoredLook(look: LookV3, compat: HeadCompat): ValidateLookResult {
  return validateLookSubmit(
    {
      gender: look.gender,
      face: look.face,
      eyes: look.eyes,
      brow: look.brow,
      mouth: look.mouth,
      nose: look.nose,
      beard: look.beard,
      skinTone: look.skinTone,
      mark: look.mark,
      hair: look.hair,
      hairColor: look.hairColor,
    },
    compat,
  );
}

export const GENERATED_LOOK_ASSERT = 'GENERATED_LOOK_ASSERT';

export interface GeneratedConstraint {
  key: 'beard' | 'nose_baked' | 'nose_required' | 'brow' | 'hair_color' | 'nose_invalid' | 'socket_mixed';
  ok: boolean;
  message: string;
  code?: string;
}

function lookAsSubmit(look: LookV3): LookSubmit {
  return {
    gender: look.gender,
    face: look.face,
    eyes: look.eyes,
    brow: look.brow,
    mouth: look.mouth,
    nose: look.nose,
    beard: look.beard,
    skinTone: look.skinTone,
    mark: look.mark,
    hair: look.hair,
    hairColor: look.hairColor,
  };
}

/**
 * 服务器生成外观的七条约束。违反视为生成器缺陷：抛内部断言，不返回 422、不重随。
 */
export function checkGeneratedConstraints(look: LookV3, compat?: HeadCompat): GeneratedConstraint[] {
  if (compat) {
    const issues = collectLookConstraintIssues(lookAsSubmit(look), compat, { requireHairColor: true });
    const keys: GeneratedConstraint['key'][] = [
      'beard',
      'nose_baked',
      'nose_required',
      'brow',
      'hair_color',
      'nose_invalid',
      'socket_mixed',
    ];
    const codeOf: Record<GeneratedConstraint['key'], string> = {
      beard: 'beard_invalid',
      nose_baked: 'nose_baked_conflict',
      nose_required: 'nose_required',
      brow: 'brow_invalid',
      hair_color: 'hair_color_invalid',
      nose_invalid: 'nose_invalid',
      socket_mixed: 'socket_mixed',
    };
    return keys.map((key) => {
      const hit = issues.find((i) => i.code === codeOf[key]);
      return {
        key,
        ok: !hit,
        message: hit ? hit.message : `${codeOf[key]} 约束满足`,
        code: codeOf[key],
      };
    });
  }
  // 无 compat 时做结构兜底（不查库、不查插槽）
  const rows: GeneratedConstraint[] = [];
  const femaleOk = look.gender !== 'f' || look.beard == null;
  const maleOk = look.gender !== 'm' || look.beard == null || look.beard.startsWith('bd_');
  rows.push({
    key: 'beard',
    ok: femaleOk && maleOk,
    message: femaleOk && maleOk ? 'beard 约束满足' : `beard 不合法 gender=${look.gender} beard=${look.beard}`,
    code: 'beard_invalid',
  });
  const baked = look.face === 'fc_01' || look.face === 'fc_02';
  rows.push({
    key: 'nose_baked',
    ok: !baked || look.nose == null,
    message: !baked || look.nose == null ? 'noseBaked 约束满足' : `noseBaked:true 但 nose=${look.nose}`,
    code: 'nose_baked_conflict',
  });
  rows.push({
    key: 'nose_required',
    ok: baked || look.nose != null,
    message: baked || look.nose != null ? 'nose 必填约束满足' : `noseBaked:false 但 nose=${look.nose}`,
    code: 'nose_required',
  });
  rows.push({
    key: 'brow',
    ok: !!look.brow,
    message: look.brow ? 'brow 约束满足' : `brow 为空或不在该性别库：${look.brow}`,
    code: 'brow_invalid',
  });
  const hcOk = !!look.hairColor && OPEN_HAIR_COLOR_SET.has(look.hairColor);
  rows.push({
    key: 'hair_color',
    ok: hcOk,
    message: hcOk ? 'hairColor 约束满足' : `hairColor 不在开放色池：${look.hairColor}`,
    code: 'hair_color_invalid',
  });
  const noseIdOk = look.nose == null || look.nose.startsWith('no_');
  rows.push({
    key: 'nose_invalid',
    ok: noseIdOk,
    message: noseIdOk ? 'nose 库约束满足' : `鼻件 ${look.nose} 不在该性别库`,
    code: 'nose_invalid',
  });
  rows.push({ key: 'socket_mixed', ok: true, message: '无 compat，跳过插槽核对', code: 'socket_mixed' });
  return rows;
}

/** 生成器 / 招募内部断言。失败抛错，调用方不得把它转成 422 或重新随机。读旧档不得调用。 */
export function assertGeneratedAppearance(look: LookV3, compat?: HeadCompat): void {
  const rows = checkGeneratedConstraints(look, compat);
  const bad = rows.filter((r) => !r.ok);
  if (bad.length) {
    const err = new Error(`${GENERATED_LOOK_ASSERT}: ${bad.map((r) => r.message).join('; ')}`);
    err.name = GENERATED_LOOK_ASSERT;
    throw err;
  }
}
