/**
 * P2 渲染：face 层内次序 ag →（预留 mk）→ no → bd → mouth/eyes（同级）→ brow。
 * 鼻走 skinmask；胡须只按清单一个 pivot 挂，并按 hairColor 渐变映射。
 * ne/nw 隐藏鼻和胡须。叠嘴一致性 overlay_consistency_c。
 */
import type { LookV3 } from './appearance_MT';
import { displayNose, isNoseBaked } from './appearance_MT';
import { hairHex, hairHiTint, skinHex, SKIN_REF } from './palette_MT';
import type { Gender, HeadCompat } from './types_MT';

export type ViewId = 'se' | 'sw' | 'ne' | 'nw' | 'side_r' | 'side_l' | 'p';
export type ExpressionId = 'neutral' | 'happy' | 'surprised' | 'tired';

export const CANVAS_W = 768;
export const CANVAS_H = 1024;

export const FACE_LAYER_ORDER = ['age', 'mk', 'nose', 'beard', 'mouth', 'eyes', 'brow'] as const;

export const FACE_Z: Record<string, number> = {
  age: 10,
  mk: 20,
  nose: 30,
  beard: 40,
  mouth: 50,
  eyes: 50,
  brow: 60,
};

export const E1_AVAILABLE_VIEWS: ViewId[] = ['se'];
export const E1_AVAILABLE_EXPRESSIONS: ExpressionId[] = ['neutral'];

export function viewHidesNoseBeard(view: ViewId): boolean {
  return view === 'ne' || view === 'nw';
}

export interface ManifestPart {
  id: string;
  slot?: string;
  partSet: string;
  gender: Gender;
  bone: string;
  layer: string;
  view: string;
  pivot: [number, number];
  file: string;
  size: [number, number];
  skinmask?: string;
  highlight?: string;
  boneOriginPx: [number, number];
  boneRotView?: number;
  category?: string;
  expression?: string;
  silhouette?: string;
  tags?: string[];
}

export interface PartsManifest {
  parts: ManifestPart[];
  [key: string]: unknown;
}

export type ArtRoot = 'e1' | 'face_redraw';

export interface PlacedPart {
  part: ManifestPart;
  root: ArtRoot;
  z: number;
  kind: 'color' | 'hi';
  fileRel: string;
}

export function partTopLeft(part: ManifestPart): { x: number; y: number } {
  const [ox, oy] = part.boneOriginPx;
  const [pw, ph] = part.size;
  const [px, py] = part.pivot;
  // 清单 pivot 常为循环小数，先四舍五入到整像素再挂，避免 0.0001 偏移把下层胡须漏进嘴实色区。
  return { x: Math.round(ox - px * pw), y: Math.round(oy - py * ph) };
}

export function hexRgb(hex: string): [number, number, number] {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
}

/** 与 W12Parts_MT.recolorSkin 同式。 */
export function recolorSkin(
  src: Uint8ClampedArray,
  mask: Uint8ClampedArray | null,
  target: string,
  ref = SKIN_REF,
): Uint8ClampedArray {
  const t = hexRgb(target);
  const r = hexRgb(ref);
  const k = [t[0] / r[0], t[1] / r[1], t[2] / r[2]];
  const out = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    const m = mask ? mask[i]! / 255 : 0;
    for (let c = 0; c < 3; c++) out[i + c] = src[i + c]! * (1 - m) + Math.min(255, src[i + c]! * k[c]!) * m;
    out[i + 3] = src[i + 3]!;
  }
  return out;
}

/** 与 W12Parts_MT.gradientMapHair 同式：暗部 → 发色×0.35，中灰 → 发色，亮部 → 发色向白 35%。 */
export function gradientMapHair(src: Uint8ClampedArray, color: string): Uint8ClampedArray {
  const c = hexRgb(color);
  const dark = c.map((v) => v * 0.35);
  const light = c.map((v) => v + (255 - v) * 0.35);
  const out = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    const l = (src[i]! * 0.299 + src[i + 1]! * 0.587 + src[i + 2]! * 0.114) / 255;
    for (let k = 0; k < 3; k++) {
      out[i + k] = l < 0.5 ? dark[k]! + (c[k]! - dark[k]!) * (l / 0.5) : c[k]! + (light[k]! - c[k]!) * ((l - 0.5) / 0.5);
    }
    out[i + 3] = src[i + 3]!;
  }
  return out;
}

export function dirOf(file: string): string {
  const i = file.lastIndexOf('/');
  return i >= 0 ? file.slice(0, i + 1) : '';
}

export interface ComposeRequest {
  look: LookV3;
  view: ViewId;
  expression: ExpressionId;
  e1: PartsManifest;
  redraw: PartsManifest;
  compat: HeadCompat;
  /** 预览缺鼻且非 baked 时显示 no_01，但不把该默认写入 look。 */
  previewDefaultNose?: boolean;
}

export function pickPart(
  manifests: { root: ArtRoot; m: PartsManifest }[],
  gender: Gender,
  partSet: string,
  view: ViewId,
  expression?: ExpressionId,
  category?: string,
): { part: ManifestPart; root: ArtRoot } | null {
  const prefer: ArtRoot[] = partSet.match(/^(no_|bd_|fc_03|ey_03|mo_03|hr_04|hr_05)/) ? ['e1', 'face_redraw'] : ['face_redraw', 'e1'];
  const ordered = [...manifests].sort((a, b) => prefer.indexOf(a.root) - prefer.indexOf(b.root));
  for (const { root, m } of ordered) {
    const hits = m.parts.filter((p) => {
      if (p.gender !== gender || p.partSet !== partSet || p.view !== view) return false;
      if (category && p.category !== category && !(category === 'hair_back' && p.category === 'hair_back') && !(category === 'hair_front' && p.category === 'hair_front')) {
        if (category === 'hair_back' || category === 'hair_front') return p.category === category;
      }
      if (p.expression && expression && p.expression !== expression) return false;
      if (category === 'hair_back') return p.category === 'hair_back' || p.bone === 'hair_b_1';
      if (category === 'hair_front') return p.category === 'hair_front';
      return true;
    });
    if (hits[0]) return { part: hits[0], root };
  }
  return null;
}

export function missingViewOrExpression(view: ViewId, expression: ExpressionId): string | null {
  const miss: string[] = [];
  if (!E1_AVAILABLE_VIEWS.includes(view)) miss.push(`视角 ${view} 暂缺（E1 只出 se）`);
  if (!E1_AVAILABLE_EXPRESSIONS.includes(expression)) miss.push(`表情 ${expression} 暂缺（E1 眼嘴只出 neutral）`);
  return miss.length ? miss.join('；') : null;
}

export function planCompose(req: ComposeRequest): { placed: PlacedPart[]; missing: string[]; hidesNoseBeard: boolean } {
  const missing: string[] = [];
  const ve = missingViewOrExpression(req.view, req.expression);
  if (ve) missing.push(ve);
  const hides = viewHidesNoseBeard(req.view);
  const manifests = [
    { root: 'e1' as const, m: req.e1 },
    { root: 'face_redraw' as const, m: req.redraw },
  ];
  const g = req.look.gender;
  const want: { set: string; cat?: string; optional?: boolean }[] = [
    { set: req.look.hair, cat: 'hair_back' },
    { set: req.look.face, cat: 'face_shape' },
    { set: req.look.mark ?? '', cat: 'age', optional: true },
    { set: req.look.mouth, cat: 'mouth' },
    { set: req.look.eyes, cat: 'eyes' },
    { set: req.look.brow, cat: 'brow' },
    { set: req.look.hair, cat: 'hair_front' },
  ];
  const baked = isNoseBaked(req.compat, g, req.look.face);
  const noseId = req.previewDefaultNose !== false ? displayNose(req.look, baked) : req.look.nose;
  if (!hides && noseId) want.splice(3, 0, { set: noseId, cat: 'nose' });
  if (!hides && req.look.beard && g === 'm') want.splice(noseId && !hides ? 4 : 3, 0, { set: req.look.beard, cat: 'beard' });

  const placed: PlacedPart[] = [];
  if (ve && req.view !== 'se') {
    return { placed, missing, hidesNoseBeard: hides };
  }
  for (const w of want) {
    if (!w.set) continue;
    const hit = pickPart(manifests, g, w.set, req.view === 'se' ? 'se' : req.view, req.expression, w.cat);
    if (!hit) {
      if (!w.optional) {
        const label = w.cat ? `${w.cat}/${w.set}/${req.view}` : `${w.set}/${req.view}`;
        if (req.view !== 'se' || (req.expression !== 'neutral' && (w.cat === 'mouth' || w.cat === 'eyes'))) {
          missing.push(`${label} 暂缺`);
        } else {
          missing.push(`${label} 未找到`);
        }
      }
      continue;
    }
    const cat = hit.part.category ?? w.cat ?? '';
    let z = 0;
    if (cat === 'hair_back') z = -20;
    else if (cat === 'face_shape' || hit.part.layer === 'head') z = 0;
    else if (cat === 'hair_front') z = 80;
    else z = FACE_Z[cat] ?? 25;
    const dir = dirOf(hit.part.file);
    placed.push({ part: hit.part, root: hit.root, z, kind: 'color', fileRel: hit.part.file });
    if (hit.part.highlight) {
      placed.push({
        part: hit.part,
        root: hit.root,
        z: z + 0.5,
        kind: 'hi',
        fileRel: `${dir}${hit.part.highlight}`,
      });
    }
  }
  placed.sort((a, b) => a.z - b.z);
  return { placed, missing, hidesNoseBeard: hides };
}

