export function artUrl(root: ArtRoot, fileRel: string): string {
  if (root === 'face_redraw' && BROW_PATCH_FILES.has(fileRel)) {
    return `./art/${BROW_PATCH_ROOT}/${fileRel}`;
  }
  if (HAIR_PATCH_FILES.has(fileRel)) {
    return `./art/${HAIR_PATCH_ROOT}/${fileRel}`;
  }
  return `./art/${root}/${fileRel}`;
}

/** 把固定蜂蜜色 _hi 换成表内高光色，并按 α 系数缩放。表外或空层原样返回。 */
export function tintHairHighlight(src: Uint8ClampedArray, hairColorId: string): Uint8ClampedArray {
  const tint = hairHiTint(hairColorId);
  if (!tint) return src;
  const h = tint.hex.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const out = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    out[i] = r;
    out[i + 1] = g;
    out[i + 2] = b;
    out[i + 3] = Math.round(src[i + 3]! * tint.alpha);
  }
  return out;
}

export function maskUrl(root: ArtRoot, part: ManifestPart): string | null {
  if (!part.skinmask) return null;
  return `./art/${root}/${dirOf(part.file)}${part.skinmask}`;
}

export type ImageLike = { width: number; height: number; data: Uint8ClampedArray };

function blendOver(dst: Uint8ClampedArray, src: Uint8ClampedArray, w: number, h: number, dx: number, dy: number, sw: number, sh: number) {
  const x0 = Math.max(0, Math.floor(dx));
  const y0 = Math.max(0, Math.floor(dy));
  const x1 = Math.min(w, Math.ceil(dx + sw));
  const y1 = Math.min(h, Math.ceil(dy + sh));
  for (let y = y0; y < y1; y++) {
    const sy = y - dy;
    if (sy < 0 || sy >= sh) continue;
    for (let x = x0; x < x1; x++) {
      const sx = x - dx;
      if (sx < 0 || sx >= sw) continue;
      const si = (Math.floor(sy) * sw + Math.floor(sx)) * 4;
      const di = (y * w + x) * 4;
      const sa = src[si + 3]! / 255;
      if (sa <= 0) continue;
      const da = dst[di + 3]! / 255;
      const outA = sa + da * (1 - sa);
      if (outA <= 0) continue;
      for (let c = 0; c < 3; c++) {
        const sv = src[si + c]!;
        const dv = dst[di + c]!;
        dst[di + c] = (sv * sa + dv * da * (1 - sa)) / outA;
      }
      dst[di + 3] = outA * 255;
    }
  }
}

export interface BitmapStore {
  get(url: string): ImageLike | undefined;
}

export function colorizePart(
  part: ManifestPart,
  kind: 'color' | 'hi',
  color: ImageLike,
  mask: ImageLike | undefined,
  look: LookV3,
): ImageLike {
  if (kind === 'hi') {
    const cat = part.category ?? '';
    if (cat === 'hair_back' || cat === 'hair_front') {
      const data = tintHairHighlight(color.data, look.hairColor);
      return { width: color.width, height: color.height, data };
    }
    return color;
  }
  const cat = part.category ?? '';
  if ((cat === 'face_shape' || cat === 'nose') && part.skinmask && mask) {
    const data = recolorSkin(color.data, mask.data, skinHex(look.skinTone));
    return { width: color.width, height: color.height, data };
  }
  if (cat === 'hair_back' || cat === 'hair_front' || cat === 'beard') {
    const data = gradientMapHair(color.data, hairHex(look.hairColor));
    return { width: color.width, height: color.height, data };
  }
  return color;
}

export function composePixels(req: ComposeRequest, store: BitmapStore): {
  width: number;
  height: number;
  data: Uint8ClampedArray;
  missing: string[];
  placed: PlacedPart[];
  hidesNoseBeard: boolean;
} {
  const plan = planCompose(req);
  const data = new Uint8ClampedArray(CANVAS_W * CANVAS_H * 4);
  for (const p of plan.placed) {
    const url = p.kind === 'hi' ? artUrl(p.root, p.fileRel) : artUrl(p.root, p.part.file);
    const raw = store.get(url);
    if (!raw) {
      plan.missing.push(`缺图 ${url}`);
      continue;
    }
    let mask: ImageLike | undefined;
    if (p.kind === 'color' && p.part.skinmask) {
      const mu = maskUrl(p.root, p.part);
      if (mu) mask = store.get(mu);
    }
    const tinted = colorizePart(p.part, p.kind, raw, mask, req.look);
    const { x, y } = partTopLeft(p.part);
    blendOver(data, tinted.data, CANVAS_W, CANVAS_H, x, y, tinted.width, tinted.height);
  }
  return { width: CANVAS_W, height: CANVAS_H, data, missing: plan.missing, placed: plan.placed, hidesNoseBeard: plan.hidesNoseBeard };
}

/** overlay_consistency_c：嘴实色区（alpha≥128）在叠胡须后 8 位 RGB 须与单放嘴一致。 */
export function overlayConsistencyC(
  mouth: ImageLike,
  mouthOrigin: { x: number; y: number },
  beard: ImageLike,
  beardOrigin: { x: number; y: number },
): { ok: boolean; mismatches: number; solidMouth: number } {
  const w = CANVAS_W;
  const h = CANVAS_H;
  const mouthOnly = new Uint8ClampedArray(w * h * 4);
  const both = new Uint8ClampedArray(w * h * 4);
  blendOver(mouthOnly, mouth.data, w, h, mouthOrigin.x, mouthOrigin.y, mouth.width, mouth.height);
  blendOver(both, beard.data, w, h, beardOrigin.x, beardOrigin.y, beard.width, beard.height);
  blendOver(both, mouth.data, w, h, mouthOrigin.x, mouthOrigin.y, mouth.width, mouth.height);
  let solid = 0;
  let mismatches = 0;
  for (let i = 0; i < mouthOnly.length; i += 4) {
    if (mouthOnly[i + 3]! < 128) continue;
    solid += 1;
    if (both[i] !== mouthOnly[i] || both[i + 1] !== mouthOnly[i + 1] || both[i + 2] !== mouthOnly[i + 2]) {
      mismatches += 1;
    }
  }
  return { ok: mismatches === 0, mismatches, solidMouth: solid };
}

/** 肤色重着色无溢色：mask=0 的像素 RGB 须与原图一致（alpha 也保留）。 */
export function skinSpillCheck(src: ImageLike, mask: ImageLike, target: string): { ok: boolean; spilled: number } {
  const out = recolorSkin(src.data, mask.data, target);
  let spilled = 0;
  for (let i = 0; i < src.data.length; i += 4) {
    if (mask.data[i]! !== 0) continue;
    if (out[i] !== src.data[i] || out[i + 1] !== src.data[i + 1] || out[i + 2] !== src.data[i + 2]) spilled += 1;
  }
  return { ok: spilled === 0, spilled };
}

/** 同一发色映射下，胡须与头发对中灰探针的输出 RGB 相同。 */
export function sameHairColorProbe(colorHex: string): { ok: boolean; hair: [number, number, number]; beard: [number, number, number] } {
  const mid = new Uint8ClampedArray([128, 128, 128, 255]);
  const a = gradientMapHair(mid, colorHex);
  const b = gradientMapHair(new Uint8ClampedArray(mid), colorHex);
  const hair: [number, number, number] = [a[0]!, a[1]!, a[2]!];
  const beard: [number, number, number] = [b[0]!, b[1]!, b[2]!];
  return { ok: hair[0] === beard[0] && hair[1] === beard[1] && hair[2] === beard[2], hair, beard };
}

export function headCropRect(gender: Gender): { x: number; y: number; w: number; h: number } {
  // 下巴在女 558 / 男 548，头高约 250，发可到更上
  const chin = gender === 'm' ? 548 : 558;
  return { x: 384 - 200, y: chin - 360, w: 400, h: 420 };
}
