/**
 * 4191 E1 发型补丁预览页：跑 P1/逻辑自检 + 像素自检 + 全部可选件贴图自检，落地 pf_01–10。
 * 以 face_redraw 被采纳为前提。不改主入口，不创建 Phaser（省内存）。
 */
import { EXPECTED_SHA256 } from './config/expectedSha_MT';
import { createLoader, HOOK_NAME, LOADER_VERSION, PREV_VERSION } from './loader_MT';
import { LOAD_ORDER_WITH_FACE_REDRAW } from './config/batches_MT';
import { runLogicSelfcheck, type E1SelfcheckReport } from './e1Selfcheck_MT';
import { canvasFromPixels, runPixelSelfcheck, type PixelCase } from './pixelSelfcheck_MT';
import { auditOfficialPresetPixels } from './presetPixel_MT';
import { composePixels, headCropRect, type PartsManifest } from './compose_MT';
import { applyTune, buildTuneFields, trySubmitLook, type TuneKey } from './faceTune_MT';
import { assertGeneratedAppearance, validateLookSubmit, type LookSubmit } from './lookValidate_MT';
import { displayNose, isNoseBaked, normalizeLook, type LookV3 } from './appearance_MT';
import { defaultLibrary } from './faceTune_MT';
import { recruitLook } from './recruit_MT';
import { auditConsoleMessage, filterLibrary } from './selectableAudit_MT';
import type { ExpandManifest, HeadCompat, LegacyIdCatalog } from './types_MT';
import {
  findPreset,
  lookFromCreatePreset,
  listPresets,
  resolvePresetId,
  validateFacePresets,
  type FacePresetsFile,
} from './presets_MT';

async function sha256Hex(buf: ArrayBuffer): Promise<string> {
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return [...new Uint8Array(hash)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

async function loadJson<T>(url: string): Promise<{ data: T; sha256: string; bytes: number }> {
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error(`加载失败 ${url}: ${res.status}`);
  const buf = await res.arrayBuffer();
  const sha = await sha256Hex(buf);
  const data = JSON.parse(new TextDecoder().decode(buf)) as T;
  return { data, sha256: sha, bytes: buf.byteLength };
}

function renderText(report: E1SelfcheckReport, pixels: PixelCase[] | null, extra: Record<string, unknown>) {
  const root = document.getElementById('out');
  if (!root) return;
  const lines: string[] = [];
  lines.push(`version: ${report.version}`);
  lines.push(`prevVersion: ${report.prevVersion}`);
  lines.push(`logicPassed: ${report.allLogicPassed}  P1 ${report.p1.passedCount}/${report.p1.cases.length}`);
  lines.push(`note: ${report.note}`);
  lines.push('');
  lines.push(`manifest sha256: ${report.sha256.manifest}  match=${report.sha256.manifestMatch}`);
  lines.push(`compat   sha256: ${report.sha256.compat}  match=${report.sha256.compatMatch}`);
  lines.push('');
  lines.push('— P1 a–e —');
  for (const c of report.p1.cases) {
    lines.push(`[${c.passed ? 'PASS' : 'FAIL'}] ${c.id} ${c.name}  ${c.reason}`);
  }
  lines.push('');
  lines.push('— §8.3 —');
  for (const c of report.items83) {
    const mark = c.pending ? (c.passed ? 'PENDING/LOGIC' : 'FAIL') : c.passed ? 'PASS' : 'FAIL';
    lines.push(`[${mark}] ${c.id} ${c.name}`);
    lines.push(`     ${c.reason}`);
  }
  if (pixels) {
    lines.push('');
    lines.push('— 像素 / 视角补全 —');
    for (const c of pixels) {
      const mark = c.pending ? (c.passed ? '暂缺' : 'FAIL') : c.passed ? 'PASS' : 'FAIL';
      lines.push(`[${mark}] ${c.id} ${c.name}`);
      lines.push(`     ${c.reason}`);
    }
  }
  lines.push('');
  lines.push('— P1–P6 —');
  for (const [k, v] of Object.entries(report.pConclusions)) {
    lines.push(`[${v.ok ? 'OK' : 'FAIL'}] ${k}  ${v.reason}`);
  }
  lines.push('');
  lines.push(JSON.stringify({ report, pixels, extra }, null, 2));
  root.textContent = lines.join('\n');
}

function setBanner(ok: boolean, text: string) {
  const banner = document.getElementById('banner');
  if (!banner) return;
  banner.textContent = text;
  banner.className = ok ? 'ok' : 'bad';
}

function paintLook(
  look: LookV3,
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
  store: { get(url: string): { width: number; height: number; data: Uint8ClampedArray } | undefined },
) {
  const pix = composePixels(
    { look, view: 'se', expression: 'neutral', e1, redraw, compat },
    store,
  );
  const crop = headCropRect(look.gender);
  const src = canvasFromPixels(pix.data, pix.width, pix.height, crop);
  const view = document.getElementById('view') as HTMLCanvasElement | null;
  if (!view) return pix;
  view.width = crop.w;
  view.height = crop.h;
  const ctx = view.getContext('2d');
  if (ctx) {
    ctx.fillStyle = '#FFF6E6';
    ctx.fillRect(0, 0, view.width, view.height);
    ctx.drawImage(src, 0, 0);
  }
  return pix;
}

function renderTune(
  look: LookV3,
  compat: HeadCompat,
  onChange: (next: LookV3) => void,
  lib = defaultLibrary(look.gender),
) {
  const root = document.getElementById('tune');
  if (!root) return;
  root.innerHTML = '';
  const submit = trySubmitLook(look, compat);
  const baked = isNoseBaked(compat, look.gender, look.face);
  const title = document.createElement('div');
  title.innerHTML = `<strong>捏脸微调（免费）</strong><div class="hint">显示鼻=${displayNose(look, baked) ?? '脸型自带'}；存档 nose=${look.nose ?? 'null'} beard=${look.beard ?? 'null'}；提交 ${submit.status}${submit.ok ? '' : ' ' + submit.issues.map((i) => i.code).join(',')}</div>`;
  root.appendChild(title);

  const gender = document.createElement('label');
  gender.innerHTML = `<span>性别</span>`;
  const gs = document.createElement('select');
  for (const g of ['f', 'm'] as const) {
    const o = document.createElement('option');
    o.value = g;
    o.textContent = g === 'f' ? '女' : '男';
    if (g === look.gender) o.selected = true;
    gs.appendChild(o);
  }
  gs.addEventListener('change', () => {
    const g = gs.value as 'f' | 'm';
    onChange(
      normalizeLook({
        ...look,
        gender: g,
        face: 'fc_03',
        eyes: 'ey_03',
        mouth: 'mo_03',
        brow: 'br_01',
        nose: 'no_01',
        beard: g === 'm' ? look.beard ?? 'bd_01' : null,
        hair: g === 'm' ? 'hr_04' : 'hr_04',
      }),
    );
  });
  gender.appendChild(gs);
  root.appendChild(gender);

  const viewHint = document.createElement('div');
  viewHint.className = 'hint';
  viewHint.textContent = '视角仅 se 可预览；side_r / p / ne / nw 暂缺。表情仅 neutral；其它表情暂缺。';
  root.appendChild(viewHint);

  for (const field of buildTuneFields(look, compat, lib)) {
    if (!field.visible) continue;
    const row = document.createElement('label');
    if (field.locked) row.className = 'locked';
    const left = document.createElement('span');
    left.textContent = field.label + (field.hint ? `（${field.hint}）` : '');
    const sel = document.createElement('select');
    sel.disabled = field.locked;
    for (const opt of field.options) {
      const o = document.createElement('option');
      o.value = opt.id;
      o.textContent = opt.label;
      o.disabled = !!opt.disabled;
      if ((field.value ?? '') === opt.id) o.selected = true;
      sel.appendChild(o);
    }
    sel.addEventListener('change', () => {
      const raw = sel.value === '' ? null : sel.value;
      onChange(applyTune(look, field.key as TuneKey, raw, compat));
    });
    row.appendChild(left);
    row.appendChild(sel);
    root.appendChild(row);
  }
}

async function main() {
  const status = document.getElementById('status');
  try {
    const [man, compat, legacy, redraw, presetsJson] = await Promise.all([
      loadJson<ExpandManifest>('./data/parts_manifest_v1.json'),
      loadJson<HeadCompat>('./data/head_compat_v1.json'),
      loadJson<LegacyIdCatalog>('./data/known_legacy_ids_MT.json'),
      loadJson<PartsManifest>('./data/face_redraw_parts_manifest_v1.json'),
      loadJson<FacePresetsFile>('./data/face_presets_v1.json'),
    ]);
    const presetsFile = presetsJson.data;
    const presetValidation = validateFacePresets(presetsFile, compat.data);
    if (!presetValidation.ok) {
      throw new Error(
        `face_presets_v1 加载失败：${presetValidation.issues.map((i) => i.code + ' ' + i.message).join(' | ')}`,
      );
    }
    const data = {
      manifest: man.data,
      compat: compat.data,
      legacyIds: legacy.data,
      sha256: { manifest: man.sha256, compat: compat.sha256 },
    };
    const logic = runLogicSelfcheck(data);
    const loader = createLoader({
      manifest: man.data,
      compat: compat.data,
      legacyIds: legacy.data,
      loadOrder: LOAD_ORDER_WITH_FACE_REDRAW,
    });
    if (status) status.textContent = '逻辑自检已完成，正在跑像素核验与出图…';

    const pixel = await runPixelSelfcheck({
      e1: man.data as unknown as PartsManifest,
      redraw: redraw.data,
      compat: compat.data,
    });

    const t9 = auditOfficialPresetPixels(
      pixel.store,
      man.data as unknown as PartsManifest,
      redraw.data,
      compat.data,
      presetsFile,
    );

    const libF = filterLibrary(defaultLibrary('f'), 'f', man.data as unknown as PartsManifest, redraw.data);
    const libM = filterLibrary(defaultLibrary('m'), 'm', man.data as unknown as PartsManifest, redraw.data);
    const libOf = (g: 'f' | 'm') => (g === 'f' ? libF.lib : libM.lib);

    const renderPresets = (look: LookV3, onChange: (next: LookV3) => void) => {
      const root = document.getElementById('presets');
      if (!root) return;
      root.innerHTML = '';
      const title = document.createElement('div');
      title.innerHTML =
        '<strong>正式预设（创角初值含 init）</strong><div class="hint">招募时预设只定五官，发型/肤色/发色按 §6.2 随机且池为 hc_01–06。以 face_redraw 被采纳为前提。</div>';
      root.appendChild(title);
      const row = document.createElement('label');
      const left = document.createElement('span');
      left.textContent = '预设';
      const sel = document.createElement('select');
      const empty = document.createElement('option');
      empty.value = '';
      empty.textContent = look.preset ? `当前 ${look.preset}` : '未选预设（已微调）';
      sel.appendChild(empty);
      for (const { ageBand, rec } of listPresets(look.gender, presetsFile)) {
        const o = document.createElement('option');
        o.value = rec.id;
        o.textContent = `${rec.id}（${ageBand === 'youth' ? '青年' : '熟龄'}）`;
        if (resolvePresetId(look.preset, presetsFile) === rec.id) o.selected = true;
        sel.appendChild(o);
      }
      sel.addEventListener('change', () => {
        if (!sel.value) return;
        onChange(lookFromCreatePreset(look.gender, sel.value, presetsFile, { appearanceSeed: look.appearanceSeed }));
      });
      row.appendChild(left);
      row.appendChild(sel);
      root.appendChild(row);
    };

    let current = pixel.shotLooks.female;
    const redrawLook = (look: LookV3) => {
      current = look;
      paintLook(look, man.data as unknown as PartsManifest, redraw.data, compat.data, pixel.store);
      renderTune(look, compat.data, redrawLook, libOf(look.gender));
      renderPresets(look, redrawLook);
      const hook = (window as unknown as Record<string, unknown>)[HOOK_NAME] as Record<string, unknown> | undefined;
      if (hook) hook.look = look;
    };
    redrawLook(current);

    const hook = {
      version: LOADER_VERSION,
      prevVersion: PREV_VERSION,
      hook: HOOK_NAME,
      loader,
      logic,
      pixels: pixel.cases,
      look: current,
      shotLooks: pixel.shotLooks,
      presets: presetsFile,
      presetValidation,
      premise: '以 face_redraw 被采纳为前提',
      listPresets: (g: 'f' | 'm') => listPresets(g, presetsFile),
      lookFromCreatePreset: (g: 'f' | 'm', id: string) => lookFromCreatePreset(g, id, presetsFile),
      resolvePresetId: (id: string | null | undefined) => resolvePresetId(id, presetsFile),
      findPreset: (g: 'f' | 'm', id: string) => findPreset(g, id, presetsFile),
      assertGeneratedAppearance: (look: LookV3) => assertGeneratedAppearance(look, compat.data),
      t9,
      applyTune: (key: TuneKey, value: string | null) => {
        const next = applyTune(current, key, value, compat.data);
        redrawLook(next);
        return next;
      },
      setLook: (look: LookV3) => {
        redrawLook(look);
        return look;
      },
      showShot: (who: 'female' | 'male') => {
        redrawLook(pixel.shotLooks[who]);
        return pixel.shotLooks[who];
      },
      recruitLook,
      trySubmitLook: (look: LookV3) => trySubmitLook(look, compat.data),
      validateLookSubmit: (submit: LookSubmit) => validateLookSubmit(submit, compat.data),
      sha256: {
        manifest: man.sha256,
        compat: compat.sha256,
        expected: EXPECTED_SHA256,
      },
      composePixels: (look: LookV3) =>
        composePixels(
          { look, view: 'se', expression: 'neutral', e1: man.data as unknown as PartsManifest, redraw: redraw.data, compat: compat.data },
          pixel.store,
        ),
      selectableAudit: pixel.selectableAudit,
      libraries: { f: libF.lib, m: libM.lib },
      droppedSelectable: [...libF.dropped, ...libM.dropped],
    };
    (window as unknown as Record<string, unknown>)[HOOK_NAME] = hook;

    const pixelFail = pixel.cases.some((c) => !c.pending && !c.passed);
    const hashOk = logic.sha256.manifestMatch === true && logic.sha256.compatMatch === true;
    const selectableOk = pixel.selectableAudit.passed;
    const t9Ok = t9.passed;
    const ok = logic.allLogicPassed && !pixelFail && hashOk && selectableOk && t9Ok;
    renderText(logic, pixel.cases, {
      bytes: { manifest: man.bytes, compat: compat.bytes, legacy: legacy.bytes, redraw: redraw.bytes, presets: presetsJson.bytes },
      premise: '以 face_redraw 被采纳为前提',
      presetValidation,
      t9,
      loader: loader.summary(),
      selectableAudit: pixel.selectableAudit,
    });
    if (!selectableOk) {
      console.error(auditConsoleMessage(pixel.selectableAudit, LOADER_VERSION));
    }
    const bannerText = ok
      ? `${LOADER_VERSION} 逻辑+像素自检通过（预览校验，非验收）`
      : !hashOk
        ? `${LOADER_VERSION} 清单哈希不符`
        : !selectableOk
          ? `${LOADER_VERSION} 可选件贴图自检不通过（预览校验，非验收）`
          : !t9Ok
            ? `${LOADER_VERSION} 预设像素自检不通过（预览校验，非验收）`
            : `${LOADER_VERSION} 自检有失败（预览校验，非验收）`;
    setBanner(ok, bannerText);
    if (status) status.textContent = '已跑完。本页只出 se 头像。以 face_redraw 被采纳为前提。不报验收通过。';
  } catch (err) {
    console.error(err);
    if (status) status.textContent = `加载或自检异常：${err}`;
    const root = document.getElementById('out');
    if (root) root.textContent = String(err);
    setBanner(false, '加载或自检异常');
    throw err;
  }
}

void main();
