/**
 * 浏览器像素自检：overlay_consistency_c、肤色溢色、发色同色、颅顶遮盖。
 * E1 没有的视角/表情标暂缺，不硬凑。
 */
import type { LookV3 } from './appearance_MT';
import {
  artUrl,
  CANVAS_H,
  CANVAS_W,
  composePixels,
  E1_AVAILABLE_EXPRESSIONS,
  E1_AVAILABLE_VIEWS,
  maskUrl,
  overlayConsistencyC,
  partTopLeft,
  pickPart,
  planCompose,
  sameHairColorProbe,
  skinSpillCheck,
  viewHidesNoseBeard,
  type ImageLike,
  type PartsManifest,
  type ViewId,
  type ExpressionId,
  type ComposeRequest,
  type BitmapStore,
} from './compose_MT';
import { HAIR_COLORS, HAIR_IDS, SKIN_IDS, skinHex, hairHex } from './palette_MT';
import type { HeadCompat } from './types_MT';
import {
  auditConsoleMessage,
  auditSelectableParts,
  collectSelectableUrls,
  type SelectableAudit,
} from './selectableAudit_MT';

export interface PixelCase {
  id: string;
  name: string;
  passed: boolean;
  pending?: boolean;
  reason: string;
  detail?: unknown;
}

async function loadImage(url: string): Promise<ImageLike> {
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error(`load ${url}: ${res.status}`);
  const blob = await res.blob();
  const bmp = await createImageBitmap(blob);
  const c = document.createElement('canvas');
  c.width = bmp.width;
  c.height = bmp.height;
  const ctx = c.getContext('2d', { willReadFrequently: true });
  if (!ctx) throw new Error('no 2d');
  ctx.drawImage(bmp, 0, 0);
  const img = ctx.getImageData(0, 0, bmp.width, bmp.height);
  bmp.close();
  return { width: img.width, height: img.height, data: img.data };
}

export class FetchStore implements BitmapStore {
  private cache = new Map<string, ImageLike>();
  async preload(urls: string[]) {
    const fails = await this.preloadSafe(urls);
    if (fails.length) {
      throw new Error(`preload failed: ${fails.map((f) => f.url + ' ' + f.error).join('; ')}`);
    }
  }
  /** 缺图记入返回值，不抛，供可选件自检把失败显示在横幅。 */
  async preloadSafe(urls: string[]): Promise<{ url: string; error: string }[]> {
    const fails: { url: string; error: string }[] = [];
    for (const u of urls) {
      if (this.cache.has(u)) continue;
      try {
        this.cache.set(u, await loadImage(u));
      } catch (err) {
        fails.push({ url: u, error: err instanceof Error ? err.message : String(err) });
      }
    }
    return fails;
  }
  get(url: string) {
    return this.cache.get(url);
  }
  has(url: string) {
    return this.cache.has(url);
  }
}

function collectUrls(req: ComposeRequest): string[] {
  const plan = planCompose(req);
  const urls: string[] = [];
  for (const p of plan.placed) {
    urls.push(p.kind === 'hi' ? artUrl(p.root, p.fileRel) : artUrl(p.root, p.part.file));
    const mu = p.kind === 'color' ? maskUrl(p.root, p.part) : null;
    if (mu) urls.push(mu);
  }
  return urls;
}

function lookBase(over: Partial<LookV3> & Pick<LookV3, 'gender'>): LookV3 {
  const g = over.gender;
  return {
    schema: 'v1.appearance.proposed.3',
    libVersion: 2,
    gender: g,
    ageBand: over.ageBand ?? 'youth',
    preset: null,
    face: over.face ?? 'fc_03',
    eyes: over.eyes ?? 'ey_03',
    brow: over.brow ?? 'br_01',
    mouth: over.mouth ?? 'mo_03',
    nose: over.nose === undefined ? 'no_01' : over.nose,
    beard: g === 'm' ? (over.beard === undefined ? 'bd_01' : over.beard) : null,
    skinTone: over.skinTone ?? 'skin_02',
    mark: over.mark ?? null,
    hair: over.hair ?? (g === 'm' ? 'hr_04' : 'hr_04'),
    hairColor: over.hairColor ?? 'hc_03',
    bodyType: 'A',
    appearanceSeed: over.appearanceSeed ?? 0,
    locked: true,
  };
}

function caseOf(id: string, name: string, passed: boolean, reason: string, detail?: unknown, pending = false): PixelCase {
  return { id, name, passed, pending, reason, detail };
}

export async function runPixelSelfcheck(input: {
  e1: PartsManifest;
  redraw: PartsManifest;
  compat: HeadCompat;
}): Promise<{ cases: PixelCase[]; store: FetchStore; shotLooks: { female: LookV3; male: LookV3 }; selectableAudit: SelectableAudit }> {
  const { e1, redraw, compat } = input;
  const store = new FetchStore();
  const cases: PixelCase[] = [];

  const female = lookBase({ gender: 'f', face: 'fc_03', nose: 'no_02', beard: null, hair: 'hr_04' });
  const male = lookBase({ gender: 'm', face: 'fc_03', nose: 'no_03', beard: 'bd_01', hair: 'hr_04' });

  const reqOf = (look: LookV3, view: ViewId = 'se', expression: ExpressionId = 'neutral'): ComposeRequest => ({
    look,
    view,
    expression,
    e1,
    redraw,
    compat,
  });

  // 问题 A：预载全部可选件贴图，不只是自检出图用到的那几张。
  const preloadLooks = [female, male, lookBase({ gender: 'm', face: 'fc_01', nose: null, beard: null, eyes: 'ey_01', mouth: 'mo_01', hair: 'hr_01' })];
  const urls = new Set<string>(collectSelectableUrls(e1, redraw, compat));
  for (const l of preloadLooks) {
    for (const u of collectUrls(reqOf(l))) urls.add(u);
  }
  // all male beards + redraw mouths for overlay
  const mouths = ['mo_01', 'mo_03'];
  const beards = ['bd_01', 'bd_02', 'bd_03', 'bd_04', 'bd_05'];
  for (const mo of mouths) {
    const hit = pickPart(
      [
        { root: 'e1', m: e1 },
        { root: 'face_redraw', m: redraw },
      ],
      'm',
      mo,
      'se',
      'neutral',
      'mouth',
    );
    if (hit) urls.add(artUrl(hit.root, hit.part.file));
  }
  for (const bd of beards) {
    const hit = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], 'm', bd, 'se', undefined, 'beard');
    if (hit) {
      urls.add(artUrl(hit.root, hit.part.file));
      if (hit.part.highlight) urls.add(artUrl(hit.root, `${hit.part.file.slice(0, hit.part.file.lastIndexOf('/') + 1)}${hit.part.highlight}`));
    }
  }
  // noses + masks for 6 skins
  for (const g of ['f', 'm'] as const) {
    const hit = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], g, 'no_01', 'se', undefined, 'nose');
    if (hit) {
      urls.add(artUrl(hit.root, hit.part.file));
      const mu = maskUrl(hit.root, hit.part);
      if (mu) urls.add(mu);
    }
  }
  const loadFailures = await store.preloadSafe([...urls]);
  const selectableAudit = auditSelectableParts(store, e1, redraw, compat, undefined, loadFailures);
  cases.push(
    caseOf(
      'A-selectable-art',
      '全部可选件贴图已预载且能画出非空像素',
      selectableAudit.passed,
      auditConsoleMessage(selectableAudit, 'A'),
      { failed: selectableAudit.failed, dropped: selectableAudit.dropped, preloaded: selectableAudit.preloaded, loadFailures },
    ),
  );

  // 5. views
  const views: ViewId[] = ['se', 'side_r', 'p', 'ne', 'nw', 'sw', 'side_l'];
  for (const v of views) {
    const hide = viewHidesNoseBeard(v);
    if (!E1_AVAILABLE_VIEWS.includes(v)) {
      cases.push(
        caseOf(
          `8.3-5-${v}`,
          `视角 ${v}`,
          true,
          hide
            ? `暂缺色图；逻辑上 ${v} 隐藏鼻和胡须（viewHidesNoseBeard=${hide}）`
            : `暂缺（E1 只出 se），不硬凑`,
          { available: E1_AVAILABLE_VIEWS, hidesNoseBeard: hide },
          true,
        ),
      );
      continue;
    }
    const r = composePixels(reqOf(male, v), store);
    const hasNose = r.placed.some((p) => p.part.category === 'nose');
    const hasBeard = r.placed.some((p) => p.part.category === 'beard');
    const ok = r.missing.length === 0 && hasNose && hasBeard && !r.hidesNoseBeard;
    cases.push(
      caseOf(
        `8.3-5-${v}`,
        `视角 ${v} 鼻、胡须`,
        ok,
        ok ? 'se 鼻、胡须已挂且未隐藏' : `失败 missing=${r.missing.join(';')} nose=${hasNose} beard=${hasBeard}`,
        { placed: r.placed.map((p) => p.part.id) },
      ),
    );
  }

  // 6. expressions / overlay
  const exprs: ExpressionId[] = ['neutral', 'happy', 'surprised', 'tired'];
  for (const ex of exprs) {
    if (!E1_AVAILABLE_EXPRESSIONS.includes(ex)) {
      cases.push(caseOf(`8.3-6-${ex}`, `表情 ${ex} 嘴不被胡须遮挡`, true, '暂缺（E1 眼嘴只出 neutral），不硬凑', { available: E1_AVAILABLE_EXPRESSIONS }, true));
      continue;
    }
  }
  const overlayRows: { mouth: string; beard: string; ok: boolean; mismatches: number; solid: number }[] = [];
  let overlayAll = true;
  for (const mo of mouths) {
    const mh = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], 'm', mo, 'se', 'neutral', 'mouth');
    if (!mh) {
      overlayAll = false;
      overlayRows.push({ mouth: mo, beard: '?', ok: false, mismatches: -1, solid: 0 });
      continue;
    }
    const mouthImg = store.get(artUrl(mh.root, mh.part.file));
    const moOrig = partTopLeft(mh.part);
    if (!mouthImg) {
      overlayAll = false;
      continue;
    }
    for (const bd of beards) {
      const bh = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], 'm', bd, 'se', undefined, 'beard');
      if (!bh) {
        overlayAll = false;
        overlayRows.push({ mouth: mo, beard: bd, ok: false, mismatches: -1, solid: 0 });
        continue;
      }
      const beardImg = store.get(artUrl(bh.root, bh.part.file));
      if (!beardImg) {
        overlayAll = false;
        continue;
      }
      const r = overlayConsistencyC(mouthImg, moOrig, beardImg, partTopLeft(bh.part));
      overlayRows.push({ mouth: mo, beard: bd, ok: r.ok, mismatches: r.mismatches, solid: r.solidMouth });
      if (!r.ok) overlayAll = false;
    }
  }
  cases.push(
    caseOf(
      '8.3-6-overlay_consistency_c',
      'neutral 叠嘴一致性 overlay_consistency_c（m/se 全部胡须 × mo_01/mo_03）',
      overlayAll,
      overlayAll ? `全部 ${overlayRows.length} 组嘴实色区与单放嘴逐像素一致` : `存在不一致：${overlayRows.filter((r) => !r.ok).map((r) => `${r.mouth}+${r.beard} mismatch=${r.mismatches}`).join('; ')}`,
      overlayRows,
    ),
  );

  // 7. 6 skins × nose no spill
  const spillRows: { gender: string; skin: string; ok: boolean; spilled: number }[] = [];
  let spillOk = true;
  for (const g of ['f', 'm'] as const) {
    const hit = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], g, 'no_01', 'se', undefined, 'nose');
    if (!hit) {
      spillOk = false;
      continue;
    }
    const src = store.get(artUrl(hit.root, hit.part.file));
    const mu = maskUrl(hit.root, hit.part);
    const mask = mu ? store.get(mu) : undefined;
    if (!src || !mask) {
      spillOk = false;
      continue;
    }
    for (const skin of SKIN_IDS) {
      const r = skinSpillCheck(src, mask, skinHex(skin));
      spillRows.push({ gender: g, skin, ok: r.ok, spilled: r.spilled });
      if (!r.ok) spillOk = false;
    }
  }
  cases.push(
    caseOf(
      '8.3-7-skin',
      '6 肤色 × 鼻无溢色',
      spillOk,
      spillOk ? 'mask=0 区 RGB 均未改变' : `溢色 ${spillRows.filter((r) => !r.ok).length} 组`,
      spillRows,
    ),
  );

  // 7. hair colors
  const hairRows = HAIR_IDS.map((id) => {
    const r = sameHairColorProbe(hairHex(id));
    return { id, official: HAIR_COLORS[id]!.official, ok: r.ok, hex: hairHex(id) };
  });
  const hairOk = hairRows.every((r) => r.ok);
  cases.push(
    caseOf(
      '8.3-7-hair',
      '10 发色 × 胡须与头发同色（同一 gradientMapHair）',
      hairOk,
      hairOk
        ? `10 档映射一致（内部自检，不经 UI 写入）；其中 hc_01–06 为已交老板 v2，hc_07–10 为预览暂定且不进捏脸下拉（正式 hc_01–10 未冻结）`
        : '存在映射不一致',
      hairRows,
    ),
  );

  // 8. new hair × faces crown coverage (se only). hats 暂缺
  cases.push(
    caseOf(
      '8.3-8-acc',
      '戴帽 / 发饰 / 眼镜不穿帮',
      true,
      '本预览包不加服装与饰品（按本批约束），该项暂缺，不硬凑',
      { note: '不加色板、K 项、服装' },
      true,
    ),
  );
  const hairSets = { f: ['hr_04', 'hr_05'], m: ['hr_04', 'hr_05'] };
  const faces = ['fc_01', 'fc_03']; // 旧新各一；最宽/最窄在像素里量
  const crownRows: { gender: string; hair: string; face: string; uncovered: number; ok: boolean; faceW: number }[] = [];
  let crownOk = true;
  for (const g of ['f', 'm'] as const) {
    const widths: { face: string; w: number }[] = [];
    for (const fc of faces) {
      const look = lookBase({
        gender: g,
        face: fc,
        nose: fc === 'fc_03' ? 'no_01' : null,
        beard: null,
        eyes: fc === 'fc_03' ? 'ey_03' : 'ey_01',
        mouth: fc === 'fc_03' ? 'mo_03' : 'mo_01',
        hair: hairSets[g][0],
      });
      const extra = collectUrls(reqOf(look)).filter((u) => !store.get(u));
      if (extra.length) await store.preloadSafe(extra);
      const pix = composePixels(reqOf(look), store);
      // measure face width from face_shape layer only? we have full composite. Use face part bbox width as proxy later.
      const fp = pix.placed.find((p) => p.part.category === 'face_shape' || p.part.partSet === fc);
      const faceW = fp ? fp.part.size[0] : 0;
      widths.push({ face: fc, w: faceW });
    }
    widths.sort((a, b) => a.w - b.w);
    const pair = [widths[0]!.face, widths[widths.length - 1]!.face];
    for (const hr of hairSets[g]) {
      for (const fc of pair) {
        const look = lookBase({
          gender: g,
          face: fc,
          nose: fc === 'fc_03' ? 'no_01' : null,
          beard: null,
          eyes: fc === 'fc_03' ? 'ey_03' : 'ey_01',
          mouth: fc === 'fc_03' ? 'mo_03' : 'mo_01',
          hair: hr,
        });
        const extra = collectUrls(reqOf(look)).filter((u) => !store.get(u));
        if (extra.length) await store.preloadSafe(extra);
        const uncovered = await crownUncovered(reqOf(look), store, e1, redraw);
        const ok = uncovered <= 8; // 少量抗锯齿允许
        crownRows.push({ gender: g, hair: hr, face: fc, uncovered, ok, faceW: (widths.find((w) => w.face === fc)?.w ?? 0) });
        if (!ok) crownOk = false;
      }
    }
  }
  cases.push(
    caseOf(
      '8.3-8-crown',
      '新发型 × 最宽/最窄脸型不露颅顶（se）',
      crownOk,
      crownOk ? '颅顶皮肤被后发或前发盖住（未覆盖像素 ≤8）' : `有露顶：${crownRows.filter((r) => !r.ok).map((r) => `${r.gender}/${r.hair}/${r.face} u=${r.uncovered}`).join('; ')}`,
      crownRows,
    ),
  );

  return { cases, store, shotLooks: { female, male }, selectableAudit };
}

/**
 * 颅顶检查：取脸型件上沿 16px 带内、水平居中 60% 的皮肤不透明像素，
 * 若合成图在这些位置没有头发（hair 层）覆盖则计为暴露。
 * 简化：在合成结果里，先单独栅格化脸型上沿，再看合成图同位置是否仍是「几乎只有皮肤」。
 * 这里用：脸型件顶部条带内 alpha≥128 的像素，若最终图该像素与「只有脸型」几乎相同（未被发丝盖住）则算暴露。
 */
async function crownUncovered(
  req: ComposeRequest,
  store: FetchStore,
  e1: PartsManifest,
  redraw: PartsManifest,
): Promise<number> {
  const g = req.look.gender;
  const fc = pickPart([{ root: 'e1', m: e1 }, { root: 'face_redraw', m: redraw }], g, req.look.face, 'se', undefined, 'face_shape');
  if (!fc) return 999;
  const faceImg = store.get(artUrl(fc.root, fc.part.file));
  if (!faceImg) return 999;
  const origin = partTopLeft(fc.part);
  const faceOnly = new Uint8ClampedArray(CANVAS_W * CANVAS_H * 4);
  // local blend
  const tmpStore: BitmapStore = store;
  const full = composePixels(req, tmpStore);
  // draw face into faceOnly
  const { data: fd, width: fw, height: fh } = faceImg;
  for (let y = 0; y < fh; y++) {
    for (let x = 0; x < fw; x++) {
      const si = (y * fw + x) * 4;
      if (fd[si + 3]! < 128) continue;
      const dx = Math.round(origin.x + x);
      const dy = Math.round(origin.y + y);
      if (dx < 0 || dy < 0 || dx >= CANVAS_W || dy >= CANVAS_H) continue;
      const di = (dy * CANVAS_W + dx) * 4;
      faceOnly[di] = fd[si]!;
      faceOnly[di + 1] = fd[si + 1]!;
      faceOnly[di + 2] = fd[si + 2]!;
      faceOnly[di + 3] = fd[si + 3]!;
    }
  }
  const band = 16;
  const yStart = Math.max(0, Math.floor(origin.y));
  const yEnd = Math.min(CANVAS_H, yStart + band);
  const xStart = Math.max(0, Math.floor(origin.x + fw * 0.2));
  const xEnd = Math.min(CANVAS_W, Math.floor(origin.x + fw * 0.8));
  let uncovered = 0;
  for (let y = yStart; y < yEnd; y++) {
    for (let x = xStart; x < xEnd; x++) {
      const i = (y * CANVAS_W + x) * 4;
      if (faceOnly[i + 3]! < 128) continue;
      // 若合成结果与纯脸型 RGB 几乎一样，说明没有头发盖上
      const dr = Math.abs(full.data[i]! - faceOnly[i]!);
      const dg = Math.abs(full.data[i + 1]! - faceOnly[i + 1]!);
      const db = Math.abs(full.data[i + 2]! - faceOnly[i + 2]!);
      if (dr + dg + db < 18 && full.data[i + 3]! >= 128) uncovered += 1;
    }
  }
  return uncovered;
}

export function canvasFromPixels(data: Uint8ClampedArray, w = CANVAS_W, h = CANVAS_H, crop?: { x: number; y: number; w: number; h: number }): HTMLCanvasElement {
  const full = document.createElement('canvas');
  full.width = w;
  full.height = h;
  const ctx = full.getContext('2d')!;
  const img = ctx.createImageData(w, h);
  img.data.set(data);
  ctx.putImageData(img, 0, 0);
  if (!crop) return full;
  const out = document.createElement('canvas');
  out.width = crop.w;
  out.height = crop.h;
  const octx = out.getContext('2d')!;
  octx.fillStyle = '#FFF6E6';
  octx.fillRect(0, 0, crop.w, crop.h);
  octx.drawImage(full, crop.x, crop.y, crop.w, crop.h, 0, 0, crop.w, crop.h);
  return out;
}

export { lookBase };
