/**
 * 肤色 / 发色表。skin_01–06 沿用已交老板 v2 色值。
 * 正式 hc_01–10 尚未冻结（face_redraw README 亦记「未定」）：
 * hc_01–06 = 老板 v2 六档；hc_07–10 仅本预览映射自测用，不写入契约、不算正式色板。
 */
export const SKIN_REF = '#FAD7BE';

export const SKIN_TONES: Record<string, string> = {
  skin_01: '#FCE6D6',
  skin_02: '#FAD7BE',
  skin_03: '#F0C09C',
  skin_04: '#DDA077',
  skin_05: '#BC7A52',
  skin_06: '#8C5636',
};

export const SKIN_IDS = ['skin_01', 'skin_02', 'skin_03', 'skin_04', 'skin_05', 'skin_06'] as const;

/** hc_01–06 已交；hc_07–10 预览暂定，官方未冻。 */
export const HAIR_COLORS: Record<string, { hex: string; official: boolean; label: string }> = {
  hc_01: { hex: '#2E2623', official: true, label: '乌黑' },
  hc_02: { hex: '#4A3428', official: true, label: '深棕' },
  hc_03: { hex: '#7A4E33', official: true, label: '栗子棕' },
  hc_04: { hex: '#B58E6B', official: true, label: '奶茶色' },
  hc_05: { hex: '#6F7F95', official: true, label: '雾灰蓝' },
  hc_06: { hex: '#D99AA5', official: true, label: '樱粉' },
  hc_07: { hex: '#C9A36A', official: false, label: '浅金（预览暂定）' },
  hc_08: { hex: '#8B3A2A', official: false, label: '红棕（预览暂定）' },
  hc_09: { hex: '#5A6B70', official: false, label: '青灰（预览暂定）' },
  hc_10: { hex: '#A0724A', official: false, label: '暖驼（预览暂定）' },
};

export const HAIR_IDS = Object.keys(HAIR_COLORS);

export const OFFICIAL_HAIR_IDS = HAIR_IDS.filter((id) => HAIR_COLORS[id]!.official);

export function skinHex(id: string): string {
  return SKIN_TONES[id] ?? SKIN_TONES.skin_02!;
}

export function hairHex(id: string): string {
  return HAIR_COLORS[id]?.hex ?? HAIR_COLORS.hc_01!.hex;
}

/**
 * 发型 _hi 调色表（未冻结）。
 * 现行源图 _hi 是固定蜂蜜色 #FFDB94，直接叠在 hc_01 上会偏浅棕。
 * 口径：高光色由该档发色本色向白提亮 0.52 得到；α 系数随发色亮度降低（深发把 α 压低）。
 * 只覆盖 hc_01–06；表外发色不改 _hi。此表未冻结，正式色板下达后可替换。
 */
export const HAIR_HI_LIFT = 0.52; // 未冻结

export interface HairHiTint {
  /** 高光色，由发色本色提亮（未冻结） */
  hex: string;
  /** 乘在原 _hi alpha 上的系数，深发更低（未冻结） */
  alpha: number;
}

export const HAIR_HI_TINTS: Record<(typeof OFFICIAL_HAIR_IDS)[number], HairHiTint> = {
  hc_01: { hex: '#9B9795', alpha: 0.42 },
  hc_02: { hex: '#A89E98', alpha: 0.50 },
  hc_03: { hex: '#BFAA9D', alpha: 0.63 },
  hc_04: { hex: '#DBC9B8', alpha: 0.88 },
  hc_05: { hex: '#BAC2CC', alpha: 0.78 },
  hc_06: { hex: '#EDCFD4', alpha: 1.00 },
};

export function hairHiTint(id: string): HairHiTint | undefined {
  return HAIR_HI_TINTS[id as keyof typeof HAIR_HI_TINTS];
}
