/**
 * 五官扩充 E1 预览类型（在 4184 加载框架上接 P1–P6）。
 * hook version: v1_lib_expand_E1_hair_patch2_1110_MT
 * prevVersion: v1_lib_expand_E1_hair_patch_1110_MT
 */

export const LOADER_VERSION = 'v1_lib_expand_E1_hair_patch2_1110_MT';
export const PREV_VERSION = 'v1_lib_expand_E1_hair_patch_1110_MT';
export const HOOK_NAME = '__v1LibExpandLoader';

export type Gender = 'f' | 'm';
export type SocketSetName = 'w2_legacy' | 'redraw_1110';

/** head_compat_v1.json 中的一条 entries 记录（旧件通常无 id，扩库 29 条有 id）。 */
export interface CompatEntry {
  gender: Gender;
  partSet: string;
  sourceBatch: string;
  socketSet: SocketSetName;
  category?: string;
  id?: string;
  noseBaked?: boolean;
  note?: string;
  view?: string;
  tags?: string[];
}

export interface ByGenderPartSetRow {
  socketSet: SocketSetName;
  category?: string;
  effectiveSource?: string;
  ids?: string[];
  id?: string;
  noseBaked?: boolean;
  note?: string;
  tags?: string[];
}

export interface HeadCompat {
  schema: string;
  draft?: boolean;
  batch?: string;
  note?: string;
  lookupKey?: string[];
  loadOrder: string[];
  socketSets: {
    w2_legacy?: { f?: SocketAnchors; m?: SocketAnchors; note?: string };
    redraw_1110?: { f?: SocketAnchors; m?: SocketAnchors; note?: string; formula_nose?: string };
  };
  entries: CompatEntry[];
  byGenderPartSet: {
    note?: string;
    f: Record<string, ByGenderPartSetRow>;
    m: Record<string, ByGenderPartSetRow>;
  };
  byId: Record<string, CompatEntry>;
  expansionIdCount?: number;
  byIdNote?: string;
}

export interface SocketAnchors {
  eye_l?: number[];
  eye_r?: number[];
  mouth?: number[];
  nose?: number[];
}

export interface ExpandPart {
  id: string;
  slot?: string;
  partSet: string;
  gender: Gender;
  category?: string;
  [key: string]: unknown;
}

export interface ExpandManifest {
  schema: string;
  patchMode: string;
  socketSet?: string;
  parts: ExpandPart[];
  [key: string]: unknown;
}

export interface LegacyIdRecord {
  id: string;
  gender: Gender;
  partSet: string;
  category?: string;
  view?: string;
  sourceBatches: string[];
}

export interface LegacyIdCatalog {
  note?: string;
  count?: number;
  ids: LegacyIdRecord[];
}

/** 角色身上要查的一件：旧件可只给 (gender, partSet)；扩库件建议带 id。 */
export interface PartRef {
  gender: Gender;
  partSet: string;
  id?: string;
}

export type LookupKind = 'byId' | 'entries' | 'parsedId+entries';

export interface ResolvedPart {
  gender: Gender;
  partSet: string;
  sourceBatch: string;
  socketSet: SocketSetName;
  category?: string;
  id?: string;
  noseBaked?: boolean;
  lookup: LookupKind;
  byIdHit: boolean;
}

export interface Issue {
  code: string;
  message: string;
  detail?: unknown;
}

export interface ValidationResult {
  ok: boolean;
  issues: Issue[];
  resolved: ResolvedPart[];
}

export interface CaseResult {
  id: string;
  name: string;
  /** 本用例按口径是否达到预期（含「应当报失败且确实报失败」）。 */
  passed: boolean;
  expectedOutcome: 'accept' | 'reject';
  actualOutcome: 'accept' | 'reject';
  reason: string;
  codes: string[];
  detail?: unknown;
}
