/**
 * 问题 A：下拉框里每个可选件都必须预载贴图，并能画出非空像素。
 * 自检遍历全部可选件（不只是当前出图用到的）。
 * 若某件在已挂载的 E1 / face_redraw 清单里确实没有 se 贴图，则从可选列表去掉，不画空白。
 */
import type { LookV3 } from './appearance_MT';
import {
  artUrl,
  composePixels,
  maskUrl,
  pickPart,
  planCompose,
  type BitmapStore,
  type ComposeRequest,
  type ImageLike,
  type PartsManifest,
} from './compose_MT';
import { defaultLibrary, type LibraryOptions } from './faceTune_MT';
import type { Gender, HeadCompat } from './types_MT';

export type SelectableKey = 'face' | 'eyes' | 'brow' | 'mouth' | 'nose' | 'beard' | 'mark' | 'hair';

export interface SelectableRef {
  gender: Gender;
  key: SelectableKey;
  id: string;
  category: string;
}

export interface SelectableItemResult {
  gender: Gender;
  key: SelectableKey;
  id: string;
  ok: boolean;
  dropped: boolean;
  reason: string;
  urls: string[];
  opaquePixels: number;
}

export interface SelectableAudit {
  passed: boolean;
  items: SelectableItemResult[];
  dropped: SelectableRef[];
  failed: SelectableItemResult[];
  preloaded: number;
  loadFailures: { url: string; error: string }[];
}

export const SELECTABLE_KEYS: { key: SelectableKey; category: string }[] = [
  { key: 'face', category: 'face_shape' },
  { key: 'eyes', category: 'eyes' },
  { key: 'brow', category: 'brow' },
  { key: 'mouth', category: 'mouth' },
  { key: 'nose', category: 'nose' },
  { key: 'beard', category: 'beard' },
  { key: 'mark', category: 'age' },
  { key: 'hair', category: 'hair' },
];

export function baseLook(gender: Gender): LookV3 {
  return {
    schema: 'v1.appearance.proposed.3',
    libVersion: 2,
    gender,
    ageBand: 'youth',
    preset: null,
    face: 'fc_03',
    eyes: 'ey_03',
    brow: 'br_01',
    mouth: 'mo_03',
    nose: 'no_01',
    beard: gender === 'm' ? 'bd_01' : null,
    skinTone: 'skin_02',
    mark: null,
    hair: gender === 'm' ? 'hr_04' : 'hr_04',
    hairColor: 'hc_03',
    bodyType: 'A',
    appearanceSeed: 0,
    locked: true,
  };
}

export function lookForPart(gender: Gender, key: SelectableKey, id: string): LookV3 {
  const look = baseLook(gender);
  if (key === 'face') {
    const baked = id === 'fc_01' || id === 'fc_02';
    return { ...look, face: id, nose: baked ? null : look.nose ?? 'no_01' };
  }
  if (key === 'eyes') return { ...look, eyes: id };
  if (key === 'brow') return { ...look, brow: id };
  if (key === 'mouth') return { ...look, mouth: id };
  if (key === 'nose') return { ...look, face: 'fc_03', nose: id };
  if (key === 'beard') return { ...look, gender: 'm', beard: id };
  if (key === 'mark') return { ...look, mark: id };
  if (key === 'hair') return { ...look, hair: id };
  return look;
}

export function listSelectableParts(libFor?: (g: Gender) => LibraryOptions): SelectableRef[] {
  const out: SelectableRef[] = [];
  for (const g of ['f', 'm'] as const) {
    const lib = (libFor ?? defaultLibrary)(g);
    const bag: Record<SelectableKey, string[]> = {
      face: lib.faces,
      eyes: lib.eyes,
      brow: lib.brows,
      mouth: lib.mouths,
      nose: lib.noses,
      beard: g === 'm' ? lib.beards : [],
      mark: lib.marks,
      hair: lib.hairs,
    };
    for (const { key, category } of SELECTABLE_KEYS) {
      for (const id of bag[key]) out.push({ gender: g, key, id, category });
    }
  }
  return out;
}

function reqOf(
  look: LookV3,
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
): ComposeRequest {
  return { look, view: 'se', expression: 'neutral', e1, redraw, compat };
}

function opaqueCount(img: ImageLike): number {
  let n = 0;
  for (let i = 3; i < img.data.length; i += 4) {
    if (img.data[i]! > 0) n += 1;
  }
  return n;
}

function urlsForLook(req: ComposeRequest): string[] {
  const plan = planCompose(req);
  const urls: string[] = [];
  for (const p of plan.placed) {
    urls.push(p.kind === 'hi' ? artUrl(p.root, p.fileRel) : artUrl(p.root, p.part.file));
    const mu = p.kind === 'color' ? maskUrl(p.root, p.part) : null;
    if (mu) urls.push(mu);
  }
  return urls;
}

/** 该可选件在清单里是否能解析到 se 色图（头发要前或后至少一层）。 */
export function hasMountedSeArt(
  gender: Gender,
  key: SelectableKey,
  id: string,
  e1: PartsManifest,
  redraw: PartsManifest,
): boolean {
  const manifests = [
    { root: 'e1' as const, m: e1 },
    { root: 'face_redraw' as const, m: redraw },
  ];
  if (key === 'hair') {
    const back = pickPart(manifests, gender, id, 'se', undefined, 'hair_back');
    const front = pickPart(manifests, gender, id, 'se', undefined, 'hair_front');
    return !!(back || front);
  }
  const category = SELECTABLE_KEYS.find((k) => k.key === key)!.category;
  return !!pickPart(manifests, gender, id, 'se', key === 'eyes' || key === 'mouth' ? 'neutral' : undefined, category);
}

export function filterLibrary(
  lib: LibraryOptions,
  gender: Gender,
  e1: PartsManifest,
  redraw: PartsManifest,
): { lib: LibraryOptions; dropped: SelectableRef[] } {
  const dropped: SelectableRef[] = [];
  const keep = (key: SelectableKey, ids: string[], category: string) => {
    const out: string[] = [];
    for (const id of ids) {
      if (hasMountedSeArt(gender, key, id, e1, redraw)) out.push(id);
      else dropped.push({ gender, key, id, category });
    }
    return out;
  };
  return {
    lib: {
      ...lib,
      faces: keep('face', lib.faces, 'face_shape'),
      eyes: keep('eyes', lib.eyes, 'eyes'),
      brows: keep('brow', lib.brows, 'brow'),
      mouths: keep('mouth', lib.mouths, 'mouth'),
      noses: keep('nose', lib.noses, 'nose'),
      beards: gender === 'm' ? keep('beard', lib.beards, 'beard') : [],
      hairs: keep('hair', lib.hairs, 'hair'),
      marks: keep('mark', lib.marks, 'age'),
    },
    dropped,
  };
}

export interface PreloadableStore extends BitmapStore {
  preloadSafe(urls: string[]): Promise<{ url: string; error: string }[]>;
  get(url: string): ImageLike | undefined;
}

export function collectSelectableUrls(
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
  refs?: SelectableRef[],
): string[] {
  const urls = new Set<string>();
  for (const ref of refs ?? listSelectableParts()) {
    for (const u of urlsForLook(reqOf(lookForPart(ref.gender, ref.key, ref.id), e1, redraw, compat))) {
      urls.add(u);
    }
  }
  return [...urls];
}

export async function preloadSelectableParts(
  store: PreloadableStore,
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
  refs?: SelectableRef[],
): Promise<{ urls: string[]; loadFailures: { url: string; error: string }[] }> {
  const urls = collectSelectableUrls(e1, redraw, compat, refs);
  const loadFailures = await store.preloadSafe(urls);
  return { urls, loadFailures };
}

export function auditSelectableParts(
  store: BitmapStore,
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
  refs?: SelectableRef[],
  loadFailures: { url: string; error: string }[] = [],
): SelectableAudit {
  const failMap = new Map(loadFailures.map((f) => [f.url, f.error]));
  const items: SelectableItemResult[] = [];
  const dropped: SelectableRef[] = [];
  for (const ref of refs ?? listSelectableParts()) {
    if (!hasMountedSeArt(ref.gender, ref.key, ref.id, e1, redraw)) {
      dropped.push(ref);
      items.push({
        gender: ref.gender,
        key: ref.key,
        id: ref.id,
        ok: true,
        dropped: true,
        reason: '已挂载清单无 se 贴图，已从可选列表去掉',
        urls: [],
        opaquePixels: 0,
      });
      continue;
    }
    const look = lookForPart(ref.gender, ref.key, ref.id);
    const req = reqOf(look, e1, redraw, compat);
    const composed = composePixels(req, store);
    const urls = urlsForLook(req);
    const missing = composed.missing.filter((m) => m.startsWith('缺图') || m.includes('未找到'));
    let opaque = 0;
    const missingUrls: string[] = [];
    const emptyUrls: string[] = [];
    for (const u of urls) {
      const img = store.get(u);
      if (!img) {
        missingUrls.push(u);
        continue;
      }
      const n = opaqueCount(img);
      opaque += n;
      // 高光 / mask 允许较稀疏，色图必须有像素；这里累加后统一判断
      if (n === 0 && !u.includes('skinmask') && !u.includes('_hi.')) emptyUrls.push(u);
    }
    let ok = missing.length === 0 && missingUrls.length === 0 && emptyUrls.length === 0 && opaque > 0;
    let reason: string;
    if (ok) {
      reason = `贴图 ${urls.length} 张已预载，不透明像素 ${opaque}`;
    } else if (missingUrls.length || missing.length) {
      const extra = missingUrls.map((u) => failMap.get(u) ?? '未预载').join('; ');
      reason = `缺图 ${[...missing, ...missingUrls].join('；')}${extra ? '（' + extra + '）' : ''}`;
      ok = false;
    } else if (emptyUrls.length || opaque === 0) {
      reason = `贴图为空像素 ${emptyUrls.join('；') || '(合计 0)'}`;
      ok = false;
    } else {
      reason = '未知失败';
    }
    items.push({
      gender: ref.gender,
      key: ref.key,
      id: ref.id,
      ok,
      dropped: false,
      reason,
      urls,
      opaquePixels: opaque,
    });
  }
  const failed = items.filter((i) => !i.ok && !i.dropped);
  return {
    passed: failed.length === 0,
    items,
    dropped,
    failed,
    preloaded: items.reduce((n, i) => n + i.urls.filter((u) => store.get(u)).length, 0),
    loadFailures,
  };
}

export function auditConsoleMessage(audit: SelectableAudit, version: string): string {
  if (audit.passed) {
    return `${version} 可选件贴图自检通过：${audit.items.filter((i) => !i.dropped).length} 件有贴图且非空像素` +
      (audit.dropped.length ? `，去掉无图件 ${audit.dropped.map((d) => `${d.gender}/${d.key}/${d.id}`).join(', ')}` : '');
  }
  const lines = audit.failed.map((f) => `${f.gender}/${f.key}/${f.id}: ${f.reason}`);
  return `${version} 可选件贴图自检不通过（${audit.failed.length} 件）：\n${lines.join('\n')}`;
}
