/**
 * P3 局部类型：appearance / profile.look 加可空 nose、beard。
 * 不改任何已通过契约文件；建议升 v1.appearance.proposed.3，见契约修订提案。
 */
import type { Gender, HeadCompat } from './types_MT';

export const LOOK_SCHEMA = 'v1.appearance.proposed.3';
/** 扩库前写入外观的 libVersion（最小集）。 */
export const LIB_VERSION_PREV = 1;
/** P5：扩库后 libVersion +1。 */
export const LIB_VERSION = LIB_VERSION_PREV + 1;

export type AgeBand = 'youth' | 'mature';

/** 局部 look / appearance（预览用）。缺 nose/beard 的旧存档按 null 读，不迁移、不重随。 */
export interface LookV3 {
  schema: typeof LOOK_SCHEMA;
  libVersion: number;
  gender: Gender;
  ageBand: AgeBand;
  preset: string | null;
  face: string;
  eyes: string;
  brow: string;
  mouth: string;
  /** null = 脸型自带鼻（noseBaked）或旧存档未写。 */
  nose: string | null;
  /** 女恒为 null；男 null = 无胡须。 */
  beard: string | null;
  skinTone: string;
  mark: string | null;
  hair: string;
  hairColor: string;
  bodyType?: 'A' | 'B';
  appearanceSeed: number;
  locked: boolean;
}

/** 旧存档 / proposed.2 可能缺的字段。 */
export type LegacyLook = Partial<LookV3> & {
  gender: Gender;
  face: string;
  eyes?: string;
  mouth?: string;
  skinTone?: string;
  hair?: string;
  hairColor?: string;
};

export function isNoseBaked(compat: HeadCompat, gender: Gender, face: string): boolean {
  const row = compat.byGenderPartSet[gender]?.[face];
  if (row && typeof row.noseBaked === 'boolean') return row.noseBaked;
  const hit = compat.entries.find(
    (e) => e.gender === gender && e.partSet === face && typeof e.noseBaked === 'boolean',
  );
  return hit?.noseBaked === true;
}

/**
 * 旧存档缺 nose/beard 时补 null，其它字段原样保留，不重随。
 * 缺 libVersion 字段按 1 读。不把预览用的 no_01 默认写进存档。
 * 旧档 preset 为 pf_youth_01 / pf_mature_01 时不改写该字段（别名在 resolvePresetId 上解析）。
 * bodyType 只记录、不加逻辑。
 */
export function normalizeLook(raw: LegacyLook, fallback: Partial<LookV3> = {}): LookV3 {
  const locked = raw.locked ?? true;
  return {
    schema: LOOK_SCHEMA,
    libVersion: raw.libVersion ?? fallback.libVersion ?? LIB_VERSION_PREV,
    gender: raw.gender,
    ageBand: raw.ageBand ?? fallback.ageBand ?? 'youth',
    preset: raw.preset ?? fallback.preset ?? null,
    face: raw.face,
    eyes: raw.eyes ?? fallback.eyes ?? 'ey_01',
    brow: raw.brow ?? fallback.brow ?? 'br_01',
    mouth: raw.mouth ?? fallback.mouth ?? 'mo_01',
    nose: raw.nose === undefined ? null : raw.nose,
    beard: raw.beard === undefined ? null : raw.beard,
    skinTone: raw.skinTone ?? fallback.skinTone ?? 'skin_02',
    mark: raw.mark === undefined ? (fallback.mark ?? null) : raw.mark,
    hair: raw.hair ?? fallback.hair ?? (raw.gender === 'm' ? 'hr_01' : 'hr_02'),
    hairColor: raw.hairColor ?? fallback.hairColor ?? 'hc_01',
    bodyType: raw.bodyType ?? fallback.bodyType ?? 'A',
    appearanceSeed: raw.appearanceSeed ?? fallback.appearanceSeed ?? 0,
    locked,
  };
}

/** 预览显示用鼻：存档仍是 null 时，noseBaked:false 可显示 no_01，但不回写。 */
export function displayNose(look: LookV3, noseBaked: boolean): string | null {
  if (noseBaked) return null;
  return look.nose ?? 'no_01';
}

export function lookFingerprint(look: LookV3): string {
  return [
    look.gender,
    look.face,
    look.eyes,
    look.brow,
    look.mouth,
    look.nose ?? '',
    look.beard ?? '',
    look.skinTone,
    look.mark ?? '',
    look.hair,
    look.hairColor,
  ].join('|');
}

/** 旧存档规范化后，除新增的 null 字段外应与原件一致。 */
export function unchangedExceptNewFields(before: LegacyLook, after: LookV3): boolean {
  const keys: (keyof LegacyLook)[] = [
    'gender',
    'face',
    'eyes',
    'brow',
    'mouth',
    'skinTone',
    'mark',
    'hair',
    'hairColor',
    'preset',
    'ageBand',
    'bodyType',
    'appearanceSeed',
    'locked',
    'libVersion',
  ];
  for (const k of keys) {
    if (before[k] === undefined) continue;
    if (before[k] !== after[k]) return false;
  }
  return after.nose === null && after.beard === null;
}
