/**
 * E1 预览自检：P1 a–e + 方案 §8.3 第 1–8 条中可不依赖浏览器像素的部分。
 * 像素项（5 视角可视化、6 叠嘴、7 换色、8 颅顶）在页面 runPixelSelfcheck 里跑。
 */
import {
  isNoseBaked,
  lookFingerprint,
  normalizeLook,
  unchangedExceptNewFields,
  LIB_VERSION,
  LIB_VERSION_PREV,
  type LegacyLook,
  type LookV3,
} from './appearance_MT';
import { EXPECTED_SHA256 } from './config/expectedSha_MT';
import { applyTune, buildTuneFields, defaultLibrary } from './faceTune_MT';
import {
  defaultRecruitLibrary,
  FEMALE_BEARD_RATE,
  MATURE_BEARD_RATE,
  measureBeardRates,
  recruitLook,
  YOUTH_BEARD_RATE,
} from './recruit_MT';
import { runSelfcheck, type SelfcheckData, type SelfcheckReport } from './selfcheck_MT';
import { validateLookSubmit } from './lookValidate_MT';
import {
  E1_AVAILABLE_EXPRESSIONS,
  E1_AVAILABLE_VIEWS,
  missingViewOrExpression,
  viewHidesNoseBeard,
} from './compose_MT';
import { LOADER_VERSION, PREV_VERSION } from './types_MT';

export interface Check83 {
  id: string;
  name: string;
  passed: boolean;
  pending?: boolean;
  reason: string;
  detail?: unknown;
}

export interface E1SelfcheckReport {
  version: string;
  prevVersion: string;
  title: string;
  note: string;
  sha256: SelfcheckReport['sha256'] & { manifestLedgerExpected: string };
  p1: SelfcheckReport;
  items83: Check83[];
  pConclusions: Record<'P1' | 'P2' | 'P3' | 'P4' | 'P5' | 'P6', { ok: boolean; reason: string }>;
  allLogicPassed: boolean;
}

function item(id: string, name: string, passed: boolean, reason: string, detail?: unknown, pending = false): Check83 {
  return { id, name, passed, pending, reason, detail };
}

function oldSaveLook(): LegacyLook {
  return {
    gender: 'f',
    face: 'fc_01',
    eyes: 'ey_01',
    brow: 'br_01',
    mouth: 'mo_01',
    skinTone: 'skin_02',
    mark: null,
    hair: 'hr_02',
    hairColor: 'hc_01',
    preset: 'pf_youth_01',
    ageBand: 'youth',
    appearanceSeed: 123456,
    locked: true,
    libVersion: LIB_VERSION_PREV,
  };
}

function near(got: number, exp: number, tol = 0.05): boolean {
  return Math.abs(got - exp) <= tol;
}

export function runLogicSelfcheck(data: SelfcheckData): E1SelfcheckReport {
  const p1 = runSelfcheck(data);
  const compat = data.compat;
  const items: Check83[] = [];

  const raw = oldSaveLook();
  const normalized = normalizeLook(raw);
  const fpBefore = [
    raw.gender,
    raw.face,
    raw.eyes,
    raw.brow,
    raw.mouth,
    raw.skinTone,
    raw.mark,
    raw.hair,
    raw.hairColor,
    raw.appearanceSeed,
    raw.locked,
    raw.libVersion,
  ].join('|');
  const fpAfterCore = [
    normalized.gender,
    normalized.face,
    normalized.eyes,
    normalized.brow,
    normalized.mouth,
    normalized.skinTone,
    normalized.mark,
    normalized.hair,
    normalized.hairColor,
    normalized.appearanceSeed,
    normalized.locked,
    normalized.libVersion,
  ].join('|');
  const ok1 =
    unchangedExceptNewFields(raw, normalized) &&
    normalized.nose === null &&
    normalized.beard === null &&
    fpBefore === fpAfterCore &&
    normalized.libVersion === LIB_VERSION_PREV;
  items.push(
    item(
      '8.3-1',
      '旧存档 / 已签约主播（无 nose / beard）加载：外观不变、不重随',
      ok1,
      ok1
        ? '缺字段按 null 读，其它 id / seed / locked / libVersion 保持不变，未重随'
        : '旧存档规范化改变了原字段或重随了外观',
      { raw, normalized, fingerprint: lookFingerprint(normalized) },
    ),
  );

  const femaleBeard = validateLookSubmit({ gender: 'f', face: 'fc_03', brow: 'br_01', nose: 'no_01', beard: 'bd_01' }, compat);
  const bakedNose = validateLookSubmit({ gender: 'm', face: 'fc_01', brow: 'br_01', nose: 'no_01', beard: null }, compat);
  const required = validateLookSubmit({ gender: 'f', face: 'fc_03', brow: 'br_01', nose: null }, compat);
  const omitted = validateLookSubmit({ gender: 'm', face: 'fc_03', brow: 'br_01', beard: null }, compat);
  const bakedNull = validateLookSubmit({ gender: 'f', face: 'fc_01', brow: 'br_01', nose: null }, compat);
  const bakedOmit = validateLookSubmit({ gender: 'm', face: 'fc_01', brow: 'br_01' }, compat);
  const emptyBrow = validateLookSubmit({ gender: 'm', face: 'fc_01', brow: '' }, compat);
  const missingBrow = validateLookSubmit({ gender: 'f', face: 'fc_01' }, compat);
  const badBrow = validateLookSubmit({ gender: 'm', face: 'fc_01', brow: 'br_99' }, compat);
  const okFemale = !femaleBeard.ok && femaleBeard.status === 422 && femaleBeard.issues.some((i) => i.code === 'beard_invalid');
  const okBaked = !bakedNose.ok && bakedNose.status === 422 && bakedNose.issues.some((i) => i.code === 'nose_baked_conflict');
  const okReq = !required.ok && required.status === 422 && required.issues.some((i) => i.code === 'nose_required');
  const okOmit = !omitted.ok && omitted.status === 422 && omitted.issues.some((i) => i.code === 'nose_required');
  const okBakedNull = bakedNull.ok && bakedNull.status === 200;
  const okBakedOmit = bakedOmit.ok && bakedOmit.status === 200;
  const okBrow =
    emptyBrow.status === 422 &&
    emptyBrow.issues.some((i) => i.code === 'brow_invalid') &&
    missingBrow.status === 422 &&
    missingBrow.issues.some((i) => i.code === 'brow_invalid') &&
    badBrow.status === 422 &&
    badBrow.issues.some((i) => i.code === 'brow_invalid');
  const ok2 = okFemale && okBaked && okReq && okOmit && okBakedNull && okBakedOmit && okBrow;
  items.push(
    item(
      '8.3-2',
      '女角色提交 beard → 422；noseBaked 脸型 + nose → 422',
      ok2,
      ok2
        ? '女+beard → 422 beard_invalid；noseBaked+nose → 422 nose_baked_conflict；noseBaked:false 提交 nose=null 或完全不带 nose 字段均 422 nose_required；noseBaked:true + null/缺字段为 200；brow 为空或非本性别库 id 均 422 brow_invalid'
        : `femaleBeard=${femaleBeard.status}/${femaleBeard.issues.map((i) => i.code).join(',')} bakedNose=${bakedNose.status} required=${required.status} omitted=${omitted.status} bakedNull=${bakedNull.status} bakedOmit=${bakedOmit.status} emptyBrow=${emptyBrow.status} missingBrow=${missingBrow.status} badBrow=${badBrow.status}`,
      { femaleBeard, bakedNose, required, omitted, bakedNull, bakedOmit, emptyBrow, missingBrow, badBrow },
    ),
  );

  const lib = defaultLibrary('m');
  const start: LookV3 = normalizeLook({
    gender: 'm',
    face: 'fc_01',
    eyes: 'ey_01',
    mouth: 'mo_01',
    skinTone: 'skin_02',
    hair: 'hr_04',
    hairColor: 'hc_01',
  });
  const fieldsBaked = buildTuneFields(start, compat, lib);
  const noseField = fieldsBaked.find((f) => f.key === 'nose');
  const beardField = fieldsBaked.find((f) => f.key === 'beard');
  const changed = applyTune(start, 'beard', 'bd_02', compat);
  const stillFree = applyTune(changed, 'hairColor', 'hc_03', compat);
  const unlockedFace = applyTune(stillFree, 'face', 'fc_03', compat);
  const withNose = applyTune(unlockedFace, 'nose', 'no_04', compat);
  const backToBaked = applyTune(withNose, 'face', 'fc_01', compat);
  const fieldsNew = buildTuneFields(withNose, compat, lib);
  const noseUnlocked = fieldsNew.find((f) => f.key === 'nose');
  const ok3 =
    !!noseField?.locked &&
    noseField.hint === '脸型自带' &&
    !!beardField?.visible &&
    changed.beard === 'bd_02' &&
    stillFree.hairColor === 'hc_03' &&
    unlockedFace.face === 'fc_03' &&
    unlockedFace.nose === 'no_01' &&
    withNose.face === 'fc_03' &&
    withNose.nose === 'no_04' &&
    backToBaked.face === 'fc_01' &&
    backToBaked.nose === null &&
    !noseUnlocked?.locked &&
    !isNoseBaked(compat, withNose.gender, withNose.face);
  items.push(
    item(
      '8.3-3',
      '捏脸：鼻 / 胡须可选、可免费改；旧脸型「鼻」项锁定',
      ok3,
      ok3
        ? 'fc_01 鼻项锁定提示「脸型自带」；可免费改胡须与发色；换到 fc_03 后状态 nose 写成 no_01（与下拉一致），可再改 no_04；换回 fc_01 置 null。无创角页，用选项/hook 验证。'
        : '锁定或免费改未达口径',
      { noseField, beardField, unlockedFace, withNose, backToBaked, noseUnlocked },
    ),
  );

  const seeds = Array.from({ length: 1000 }, (_, i) => i + 1);
  const tuneYouth = measureBeardRates(seeds, { forceGender: 'm', forceAge: 'youth', forceBranch: 'tune' });
  const tuneMature = measureBeardRates(seeds, { forceGender: 'm', forceAge: 'mature', forceBranch: 'tune' });
  const tuneFemale = measureBeardRates(seeds, { forceGender: 'f', forceAge: 'youth', forceBranch: 'tune' });
  const mixed = measureBeardRates(seeds);
  const rateOk =
    near(tuneYouth.youthMale.rate, YOUTH_BEARD_RATE) &&
    near(tuneMature.matureMale.rate, MATURE_BEARD_RATE) &&
    tuneFemale.female.rate === FEMALE_BEARD_RATE &&
    tuneYouth.sameSeedRepeats &&
    tuneMature.sameSeedRepeats &&
    tuneFemale.sameSeedRepeats &&
    mixed.sameSeedRepeats &&
    mixed.female.rate === 0;
  items.push(
    item(
      '8.3-4',
      '招募：1,000 个 seed；胡须率青年约 30% / 熟龄约 55%，女 0%；同 seed 复现',
      rateOk,
      rateOk
        ? `微调支路 1000 seed：青年 ${(tuneYouth.youthMale.rate * 100).toFixed(1)}%（目标 30%±5pp），熟龄 ${(tuneMature.matureMale.rate * 100).toFixed(1)}%（目标 55%±5pp），女 0%；同 seed 复现。含正式预设的混合抽取青年 ${((mixed.youthMale.rate || 0) * 100).toFixed(1)}% / 熟龄 ${((mixed.matureMale.rate || 0) * 100).toFixed(1)}%（目标约 32% / 52%）。libVersion=${LIB_VERSION}（写入 appearance；旧档缺字段按 1 读）。`
        : `微调支路未达目标：youth=${tuneYouth.youthMale.rate} mature=${tuneMature.matureMale.rate} female=${tuneFemale.female.rate} repeat=${tuneYouth.sameSeedRepeats}`,
      { tuneYouth, tuneMature, tuneFemale, mixed, libVersion: LIB_VERSION },
    ),
  );

  items.push(
    item(
      '8.3-5',
      '视角：se / side_r / p 鼻、胡须正确；ne / nw 隐藏；镜像无错位',
      true,
      `逻辑：ne/nw 隐藏鼻和胡须已实现（ne=${viewHidesNoseBeard('ne')}, nw=${viewHidesNoseBeard('nw')}）。色图方面 E1 只出 se，side_r / p / ne / nw / 镜像标暂缺，不硬凑。像素核验在页面跑。`,
      {
        availableViews: E1_AVAILABLE_VIEWS,
        missing: (['side_r', 'p', 'ne', 'nw', 'sw', 'side_l'] as const).map((v) => missingViewOrExpression(v, 'neutral')),
      },
      true,
    ),
  );
  items.push(
    item(
      '8.3-6',
      '表情：4 表情下嘴不被胡须遮挡',
      true,
      '逻辑：层序胡须在嘴下，判据 overlay_consistency_c。E1 眼嘴只出 neutral，happy/surprised/tired 标暂缺。像素核验在页面跑。',
      { availableExpressions: E1_AVAILABLE_EXPRESSIONS },
      true,
    ),
  );
  items.push(
    item(
      '8.3-7',
      '换色：6 肤色 × 鼻无溢色；10 发色 × 胡须与头发同色',
      true,
      '公式已接入（鼻 skinmask、胡须与发型同一 gradientMapHair）。十档映射自检只在内部跑，不经 UI 写入；捏脸下拉只列 hc_01–06。hc_07–10 仍为预览暂定色，不进选项。',
      undefined,
      true,
    ),
  );
  items.push(
    item(
      '8.3-8',
      '组合：新发型 × 最宽/最窄脸型不露颅顶；戴帽/发饰/眼镜不穿帮',
      true,
      '颅顶像素核验在页面跑。戴帽/发饰/眼镜因本批不加服装与饰品，标暂缺。',
      undefined,
      true,
    ),
  );

  const emptyLib = defaultRecruitLibrary('m', compat);
  emptyLib.beards = [];
  const empty = recruitLook({
    recruitSeed: 99,
    gender: 'm',
    ageBand: 'youth',
    forceBranch: 'tune',
    lib: emptyLib,
  });
  const emptyOk = empty.look.beard === null && empty.beardMeta.poolEmpty === true;

  const pConclusions: E1SelfcheckReport['pConclusions'] = {
    P1: {
      ok: p1.allPassed,
      reason: p1.allPassed
        ? 'append 重名报错；socketSet 按实际 loadOrder 从 entries 解析；未挂 face_redraw 不用预合并表；byId 只覆盖扩库 29 条；缺扩库 id 失败；ey_02/mo_02 不上新脸'
        : 'P1 自检未全过',
    },
    P2: {
      ok: true,
      reason:
        '层序 ag→mk→no→bd→mouth/eyes→brow 已实现；鼻 skinmask；胡须单 pivot + hairColor 映射；ne/nw 隐藏；overlay_consistency_c 在页面跑。E1 缺视角/表情标暂缺。',
    },
    P3: {
      ok: ok1,
      reason: ok1
        ? '局部类型已加可空 nose/beard；旧存档缺 nose/beard 按 null、缺 libVersion 按 1 读，不重随；未改契约定稿原文'
        : '旧存档规范化未达口径',
    },
    P4: {
      ok: ok3,
      reason: ok3
        ? '微调项已加鼻、胡须（男）；noseBaked 锁定并提示「脸型自带」；换到 fc_03 时状态写入 no_01，换回 baked 脸置 null'
        : '捏脸选项未达口径',
    },
    P5: {
      ok: rateOk && emptyOk,
      reason:
        rateOk && emptyOk
          ? `招募按 §2.9/§2.10；libVersion ${LIB_VERSION_PREV}→${LIB_VERSION}；青年短须池、池空不报错；女 0%；同 seed 复现`
          : '招募随机或池空处理未达口径',
    },
    P6: {
      ok: ok2,
      reason: '本地校验七条（定稿小写码）：beard_invalid、nose_baked_conflict、nose_required、brow_invalid、hair_color_invalid、nose_invalid、socket_mixed。profile/look 返 422；生成外观用内部断言拦住，不返 422、不重随。读旧档不校验。不部署服务端。',
    },
  };

  return {
    version: LOADER_VERSION,
    prevVersion: PREV_VERSION,
    title: 'V1 五官扩充 E1 发型补丁自检（P1–P6 / §8.3 / T1–T12，非验收）',
    note: '以 face_redraw 被采纳为前提。数字不冻结，不是整包 V1，不报验收通过。本批只在预览端口落地。E1 只有 se 与 neutral，缺项标暂缺。',
    sha256: { ...p1.sha256, manifestLedgerExpected: EXPECTED_SHA256.manifest_ledger },
    p1,
    items83: items,
    pConclusions,
    allLogicPassed: p1.allPassed && items.filter((i) => !i.pending).every((i) => i.passed) && emptyOk,
  };
}
