/**
 * 加载批次名与 loadOrder 规则。
 * 例：W2_1110 → ne_patch → face_redraw（若本次挂入）→ lib_expand_*（append）。
 * byGenderPartSet 是假设完整 loadOrder 的预合并视图，不得在未挂 face_redraw 时直接采用。
 */

export const BATCH_W2 = 'parts_v1_W2_1110';
export const BATCH_NE = 'parts_v1_W2_ne_patch_1110';
export const BATCH_FACE_REDRAW = 'parts_v1_W2_face_redraw_1110';
export const BATCH_EXPAND_PATTERN = 'parts_v1_W2_lib_expand_*';
export const BATCH_EXPAND_E1 = 'parts_v1_W2_lib_expand_E1_1110';
export const BATCH_EXPAND_A0 = 'parts_v1_W2_lib_expand_A0_1110';

/** A0 head_compat 记录的完整 loadOrder（预合并 byGenderPartSet 所依据的假设链）。 */
export const COMPAT_FULL_LOAD_ORDER: readonly string[] = [
  BATCH_W2,
  BATCH_NE,
  BATCH_FACE_REDRAW,
  BATCH_EXPAND_PATTERN,
];

/** E1 对稿默认挂入：W2 + ne + face_redraw + E1 expand。 */
export const LOAD_ORDER_WITH_FACE_REDRAW: readonly string[] = [
  BATCH_W2,
  BATCH_NE,
  BATCH_FACE_REDRAW,
  BATCH_EXPAND_E1,
];

/** 未挂 face_redraw：仅 W2 + ne + expand。此时旧件仍为 w2_legacy。 */
export const LOAD_ORDER_WITHOUT_FACE_REDRAW: readonly string[] = [
  BATCH_W2,
  BATCH_NE,
  BATCH_EXPAND_E1,
];

export function isFaceRedrawBatch(id: string): boolean {
  return id.includes('face_redraw');
}

export function isExpandBatch(id: string): boolean {
  return /parts_v1_W2_lib_expand_/.test(id);
}

export function isFaceRedrawMounted(loadOrder: readonly string[]): boolean {
  return loadOrder.some(isFaceRedrawBatch);
}

/**
 * entries[].sourceBatch 是否属于本次实际挂入的某一批次。
 * A0 备稿 entries 的 sourceBatch 写的是 draftOf E1 名；
 * 挂入 A0 或 lib_expand_* 通配时都应命中这些行。
 */
export function sourceBatchMatches(sourceBatch: string, mounted: string): boolean {
  const m = mounted.trim();
  if (!m) return false;
  if (m.endsWith('*')) return sourceBatch.startsWith(m.slice(0, -1));
  if (sourceBatch === m) return true;
  // 挂入任一 lib_expand 包，即启用 compat 里的 lib_expand_E1 / A0 entries
  if (isExpandBatch(m) && isExpandBatch(sourceBatch)) return true;
  return false;
}

/** 在本次 loadOrder 中的秩；未挂入返回 -1。后者覆盖前者。 */
export function loadOrderRank(sourceBatch: string, loadOrder: readonly string[]): number {
  let rank = -1;
  for (let i = 0; i < loadOrder.length; i++) {
    if (sourceBatchMatches(sourceBatch, loadOrder[i]!)) rank = i;
  }
  return rank;
}
