/**
 * T9：20 个正式预设 se 合成像素核验（挂点不混用、胡须越下颌、嘴区一致、fc_03 鼻 mask）。
 */
import type { HeadCompat } from './types_MT';
import {
  composePixels,
  overlayConsistencyC,
  pickPart,
  partTopLeft,
  artUrl,
  maskUrl,
  skinSpillCheck,
  type PartsManifest,
  type ImageLike,
} from './compose_MT';
import { skinHex } from './palette_MT';
import { listPresets, lookFromCreatePreset, type FacePresetsFile } from './presets_MT';
import type { LookV3 } from './appearance_MT';

export interface PresetPixelRow {
  gender: 'f' | 'm';
  id: string;
  ok: boolean;
  missing: string[];
  socketMix: string[];
  beardOverflowPx: number | null;
  overlayOk: boolean | null;
  noseSpill: number | null;
  reason: string;
}

function chebyshevOverflow(face: ImageLike, facePos: { x: number; y: number }, beard: ImageLike, beardPos: { x: number; y: number }): number {
  const pad = 8;
  const x0 = Math.floor(Math.min(facePos.x, beardPos.x)) - pad;
  const y0 = Math.floor(Math.min(facePos.y, beardPos.y)) - pad;
  const x1 = Math.ceil(Math.max(facePos.x + face.width, beardPos.x + beard.width)) + pad;
  const y1 = Math.ceil(Math.max(facePos.y + face.height, beardPos.y + beard.height)) + pad;
  const w = x1 - x0;
  const h = y1 - y0;
  const INF = 1e9;
  const dist = new Float64Array(w * h);
  dist.fill(INF);
  const qx: number[] = [];
  const qy: number[] = [];
  for (let y = 0; y < face.height; y++) {
    for (let x = 0; x < face.width; x++) {
      if (face.data[(y * face.width + x) * 4 + 3]! < 128) continue;
      const gx = Math.floor(facePos.x) + x - x0;
      const gy = Math.floor(facePos.y) + y - y0;
      if (gx < 0 || gy < 0 || gx >= w || gy >= h) continue;
      const i = gy * w + gx;
      if (dist[i] !== 0) {
        dist[i] = 0;
        qx.push(gx);
        qy.push(gy);
      }
    }
  }
  for (let i = 0; i < qx.length; i++) {
    const cx = qx[i]!, cy = qy[i]!;
    const d = dist[cy * w + cx]!;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        const ni = ny * w + nx;
        const nd = d + 1;
        if (nd < dist[ni]!) {
          dist[ni] = nd;
          qx.push(nx);
          qy.push(ny);
        }
      }
    }
  }
  let max = 0;
  let any = false;
  for (let y = 0; y < beard.height; y++) {
    for (let x = 0; x < beard.width; x++) {
      if (beard.data[(y * beard.width + x) * 4 + 3]! < 128) continue;
      any = true;
      const gx = Math.floor(beardPos.x) + x - x0;
      const gy = Math.floor(beardPos.y) + y - y0;
      if (gx < 0 || gy < 0 || gx >= w || gy >= h) {
        max = Math.max(max, INF);
        continue;
      }
      const d = dist[gy * w + gx]!;
      if (d > max) max = d;
    }
  }
  return any ? max : 0;
}

export function auditOfficialPresetPixels(
  store: { get(url: string): ImageLike | undefined },
  e1: PartsManifest,
  redraw: PartsManifest,
  compat: HeadCompat,
  presets: FacePresetsFile,
): { passed: boolean; rows: PresetPixelRow[] } {
  const manifests = [
    { root: 'e1' as const, m: e1 },
    { root: 'face_redraw' as const, m: redraw },
  ];
  const rows: PresetPixelRow[] = [];
  for (const gender of ['f', 'm'] as const) {
    for (const { rec } of listPresets(gender, presets)) {
      const look: LookV3 = lookFromCreatePreset(gender, rec.id, presets);
      const pix = composePixels({ look, view: 'se', expression: 'neutral', e1, redraw, compat }, store);
      const socketMix: string[] = [];
      for (const p of pix.placed) {
        const row = compat.byGenderPartSet[gender]?.[p.part.partSet];
        if (row && row.socketSet && row.socketSet !== presets.socketSet) {
          socketMix.push(`${p.part.partSet}:${row.socketSet}`);
        }
      }
      let beardOverflowPx: number | null = null;
      let overlayOk: boolean | null = null;
      if (look.beard) {
        const faceHit = pix.placed.find((p) => p.part.category === 'face_shape' || p.part.partSet === look.face);
        const beardHit = pix.placed.find((p) => p.part.category === 'beard' || p.part.partSet === look.beard);
        if (faceHit && beardHit) {
          const faceImg = store.get(artUrl(faceHit.root, faceHit.part.file));
          const beardImg = store.get(artUrl(beardHit.root, beardHit.part.file));
          if (faceImg && beardImg) {
            beardOverflowPx = chebyshevOverflow(faceImg, partTopLeft(faceHit.part), beardImg, partTopLeft(beardHit.part));
          }
        }
        const mh = pickPart(manifests, 'm', look.mouth, 'se', 'neutral', 'mouth');
        const bh = pickPart(manifests, 'm', look.beard, 'se', undefined, 'beard');
        if (mh && bh) {
          const mouthImg = store.get(artUrl(mh.root, mh.part.file));
          const beardImg = store.get(artUrl(bh.root, bh.part.file));
          if (mouthImg && beardImg) {
            overlayOk = overlayConsistencyC(mouthImg, partTopLeft(mh.part), beardImg, partTopLeft(bh.part)).ok;
          } else {
            overlayOk = false;
          }
        }
      }
      let noseSpill: number | null = null;
      if (look.face === 'fc_03' && look.nose) {
        const nh = pickPart(manifests, gender, look.nose, 'se', undefined, 'nose');
        if (nh) {
          const src = store.get(artUrl(nh.root, nh.part.file));
          const mu = maskUrl(nh.root, nh.part);
          const mask = mu ? store.get(mu) : undefined;
          if (src && mask) {
            const r = skinSpillCheck(src, mask, skinHex(look.skinTone));
            noseSpill = r.spilled;
          } else {
            noseSpill = -1;
          }
        }
      }
      const problems: string[] = [];
      if (pix.missing.length) problems.push(`missing=${pix.missing.join(',')}`);
      if (socketMix.length) problems.push(`socketMix=${socketMix.join(',')}`);
      if (beardOverflowPx != null && beardOverflowPx > 6) problems.push(`beardOverflow=${beardOverflowPx}px`);
      if (overlayOk === false) problems.push('overlay_consistency_c fail');
      if (noseSpill != null && noseSpill > 0) problems.push(`noseSpill=${noseSpill}`);
      if (noseSpill === -1) problems.push('nose mask missing');
      const ok = problems.length === 0;
      rows.push({
        gender,
        id: rec.id,
        ok,
        missing: pix.missing,
        socketMix,
        beardOverflowPx,
        overlayOk,
        noseSpill,
        reason: ok ? 'pass' : problems.join('; '),
      });
    }
  }
  return { passed: rows.every((r) => r.ok), rows };
}
