/**
 * P4 捏脸微调：加「鼻」「胡须（男）」。脸型 noseBaked 时鼻项锁定并提示。
 * 本预览无独立创角页，用 hook / 页面选项验证；改外观免费（不收费）。
 */
import { displayNose, isNoseBaked, type LookV3 } from './appearance_MT';
import { validateLookSubmit } from './lookValidate_MT';
import type { Gender, HeadCompat } from './types_MT';

export interface TuneOption {
  id: string;
  label: string;
  disabled?: boolean;
  hint?: string;
}

export interface TuneField {
  key: 'face' | 'eyes' | 'brow' | 'mouth' | 'nose' | 'beard' | 'skinTone' | 'mark' | 'hair' | 'hairColor';
  label: string;
  visible: boolean;
  locked: boolean;
  hint?: string;
  value: string | null;
  options: TuneOption[];
}

export interface LibraryOptions {
  faces: string[];
  eyes: string[];
  brows: string[];
  mouths: string[];
  noses: string[];
  beards: string[];
  hairs: string[];
  skinTones: string[];
  hairColors: string[];
  marks: string[];
}

export function defaultLibrary(gender: Gender): LibraryOptions {
  const noses = ['no_01', 'no_02', 'no_03', 'no_04', 'no_05'];
  return {
    faces: ['fc_01', 'fc_02', 'fc_03'],
    eyes: ['ey_01', 'ey_03'], // ey_02 为 w2_legacy，挂新脸会混 socketSet
    brows: ['br_01'],
    mouths: ['mo_01', 'mo_03'],
    noses,
    beards: gender === 'm' ? ['bd_01', 'bd_02', 'bd_03', 'bd_04', 'bd_05'] : [],
    hairs: gender === 'm' ? ['hr_01', 'hr_04', 'hr_05'] : ['hr_02', 'hr_04', 'hr_05'],
    skinTones: ['skin_01', 'skin_02', 'skin_03', 'skin_04', 'skin_05', 'skin_06'],
    // 捏脸下拉只列正式 hc_01–06；hc_07–10 不进 UI，十档映射自检走 palette.HAIR_IDS 内部路径。
    hairColors: ['hc_01', 'hc_02', 'hc_03', 'hc_04', 'hc_05', 'hc_06'],
    marks: ['ag_01'],
  };
}

export function buildTuneFields(look: LookV3, compat: HeadCompat, lib: LibraryOptions = defaultLibrary(look.gender)): TuneField[] {
  const baked = isNoseBaked(compat, look.gender, look.face);
  const noseLocked = baked;
  const fields: TuneField[] = [
    {
      key: 'face',
      label: '脸型',
      visible: true,
      locked: false,
      value: look.face,
      options: lib.faces.map((id) => ({ id, label: id })),
    },
    {
      key: 'eyes',
      label: '眼',
      visible: true,
      locked: false,
      value: look.eyes,
      options: lib.eyes.map((id) => ({ id, label: id })),
    },
    {
      key: 'brow',
      label: '眉',
      visible: true,
      locked: false,
      value: look.brow,
      options: lib.brows.map((id) => ({ id, label: id })),
    },
    {
      key: 'mouth',
      label: '嘴',
      visible: true,
      locked: false,
      value: look.mouth,
      options: lib.mouths.map((id) => ({ id, label: id })),
    },
    {
      key: 'nose',
      label: '鼻',
      visible: true,
      locked: noseLocked,
      hint: noseLocked ? '脸型自带' : undefined,
      value: noseLocked ? null : displayNose(look, false),
      options: noseLocked
        ? [{ id: '', label: '脸型自带', disabled: true, hint: '脸型自带' }]
        : lib.noses.map((id) => ({ id, label: id })),
    },
    {
      key: 'beard',
      label: '胡须（男）',
      visible: look.gender === 'm',
      locked: look.gender !== 'm',
      value: look.gender === 'm' ? look.beard : null,
      options:
        look.gender === 'm'
          ? [{ id: '', label: '无' }, ...lib.beards.map((id) => ({ id, label: id }))]
          : [{ id: '', label: '无（女库不建）', disabled: true }],
    },
    {
      key: 'skinTone',
      label: '肤色',
      visible: true,
      locked: false,
      value: look.skinTone,
      options: lib.skinTones.map((id) => ({ id, label: id })),
    },
    {
      key: 'mark',
      label: '年龄细节',
      visible: true,
      locked: false,
      value: look.mark,
      options: [{ id: '', label: '无' }, ...lib.marks.map((id) => ({ id, label: id }))],
    },
    {
      key: 'hair',
      label: '发型',
      visible: true,
      locked: false,
      value: look.hair,
      options: lib.hairs.map((id) => ({ id, label: id })),
    },
    {
      key: 'hairColor',
      label: '发色',
      visible: true,
      locked: false,
      value: look.hairColor,
      options: lib.hairColors.map((id) => ({ id, label: id })),
    },
  ];
  return fields;
}

export type TuneKey = TuneField['key'];

/** 免费改一项。鼻在 noseBaked 时拒绝；胡须在女角色上拒绝。返回新 look（未校验提交）。 */
export function applyTune(look: LookV3, key: TuneKey, value: string | null, compat: HeadCompat): LookV3 {
  const baked = isNoseBaked(compat, look.gender, look.face);
  if (key === 'face') {
    const nextFace = value ?? look.face;
    const nextBaked = isNoseBaked(compat, look.gender, nextFace);
    // 方案 §2.4：换到 noseBaked:false 的脸时把 nose 写成 no_01（若还没有值）；换回 baked 脸置 null。
    return {
      ...look,
      face: nextFace,
      nose: nextBaked ? null : (look.nose ?? 'no_01'),
      preset: null,
    };
  }
  if (key === 'nose') {
    if (baked) return { ...look, nose: null };
    return { ...look, nose: value, preset: null };
  }
  if (key === 'beard') {
    if (look.gender !== 'm') return { ...look, beard: null };
    return { ...look, beard: value, preset: null };
  }
  if (key === 'mark') return { ...look, mark: value, preset: null };
  if (value == null) return look;
  return { ...look, [key]: value, preset: null };
}

export function trySubmitLook(look: LookV3, compat: HeadCompat) {
  return validateLookSubmit(
    {
      gender: look.gender,
      face: look.face,
      nose: look.nose,
      beard: look.beard,
      eyes: look.eyes,
      brow: look.brow,
      mouth: look.mouth,
      skinTone: look.skinTone,
      mark: look.mark,
      hair: look.hair,
      hairColor: look.hairColor,
    },
    compat,
  );
}
