/**
 * E1 预览 P1 自检用例 a–e。写到程序临时目录，不覆写美术交付。
 * 本文件只断言 P1 口径，不报验收通过。
 */
import {
  LOAD_ORDER_WITH_FACE_REDRAW,
  LOAD_ORDER_WITHOUT_FACE_REDRAW,
} from './config/batches_MT';
import { EXPECTED_SHA256 } from './config/expectedSha_MT';
import { createLoader, LOADER_VERSION } from './loader_MT';
import type {
  CaseResult,
  ExpandManifest,
  HeadCompat,
  Issue,
  LegacyIdCatalog,
  PartRef,
} from './types_MT';

export interface SelfcheckData {
  manifest: ExpandManifest;
  compat: HeadCompat;
  legacyIds: LegacyIdCatalog;
  sha256?: {
    manifest?: string;
    compat?: string;
  };
}

export interface SelfcheckReport {
  version: string;
  title: string;
  note: string;
  sha256: {
    manifest?: string;
    manifestExpected: string;
    manifestMatch?: boolean;
    compat?: string;
    compatExpected: string;
    compatMatch?: boolean;
  };
  cases: CaseResult[];
  allPassed: boolean;
  passedCount: number;
  failedCount: number;
}

function codesOf(issues: Issue[]): string[] {
  return issues.map((i) => i.code);
}

function ref(gender: PartRef['gender'], partSet: string, id?: string): PartRef {
  return id ? { gender, partSet, id } : { gender, partSet };
}

function caseResult(
  id: string,
  name: string,
  expected: 'accept' | 'reject',
  actualOk: boolean,
  reason: string,
  issues: Issue[] = [],
  detail?: unknown,
  forcePassed?: boolean,
): CaseResult {
  const actual: 'accept' | 'reject' = actualOk ? 'accept' : 'reject';
  const passed = forcePassed != null ? forcePassed : actual === expected;
  return {
    id,
    name,
    passed,
    expectedOutcome: expected,
    actualOutcome: actual,
    reason: passed ? reason : `未达预期（期望 ${expected}，实际 ${actual}）：${reason}`,
    codes: codesOf(issues),
    detail,
  };
}

/** a) 挂入 face_redraw + E1 expand：29 条 byId 命中；旧件按 entries 可查；组合均为 redraw_1110。 */
function caseA(data: SelfcheckData): CaseResult {
  const loader = createLoader({
    manifest: data.manifest,
    compat: data.compat,
    legacyIds: data.legacyIds,
    loadOrder: LOAD_ORDER_WITH_FACE_REDRAW,
  });
  const pkg = loader.validatePackage();
  if (!pkg.ok) {
    return caseResult('a', '挂入 face_redraw + E1 expand', 'accept', false, '包级校验失败', pkg.issues, pkg);
  }

  const expandIds = data.manifest.parts.map((p) => p.id);
  const missed = expandIds.filter((id) => !data.compat.byId[id]);
  if (missed.length || expandIds.length !== 29 || Object.keys(data.compat.byId).length !== 29) {
    return caseResult(
      'a',
      '挂入 face_redraw + E1 expand',
      'accept',
      false,
      `扩库 byId 未完整命中 29 条（清单 ${expandIds.length}，byId ${Object.keys(data.compat.byId).length}，缺 ${missed.join(',') || '无'}）`,
    );
  }

  const oldIds: PartRef[] = [
    ref('f', 'fc_01', 'part_f_head_fc_01_head_se'),
    ref('f', 'ey_01', 'part_f_head_ey_01_head_se_neutral'),
    ref('f', 'mo_01', 'part_f_head_mo_01_head_se_neutral'),
    ref('m', 'fc_01', 'part_m_head_fc_01_head_se'),
    ref('m', 'ey_01', 'part_m_head_ey_01_head_se_neutral'),
    ref('m', 'mo_01', 'part_m_head_mo_01_head_se_neutral'),
  ];
  const oldResolved = [];
  for (const r of oldIds) {
    const got = loader.resolve(r);
    if (!got.ok) {
      return caseResult('a', '挂入 face_redraw + E1 expand', 'accept', false, `旧件查询失败：${r.id}`, got.issues);
    }
    if (got.resolved.some((row) => row.byIdHit)) {
      return caseResult(
        'a',
        '挂入 face_redraw + E1 expand',
        'accept',
        false,
        `旧件 ${r.id} 不应出现在 byId 中（byId 只覆盖扩库 29 条）`,
        [],
        got.resolved,
      );
    }
    if (!got.byIdMissingButResolvedViaEntries) {
      return caseResult(
        'a',
        '挂入 face_redraw + E1 expand',
        'accept',
        false,
        `旧件 ${r.id} 缺 byId 时应走 entries，且不得当失败`,
        [],
        got,
      );
    }
    if (got.resolved.some((row) => row.socketSet !== 'redraw_1110')) {
      return caseResult(
        'a',
        '挂入 face_redraw + E1 expand',
        'accept',
        false,
        `挂入 face_redraw 后旧件 ${r.partSet} 应为 redraw_1110`,
        [],
        got.resolved,
      );
    }
    oldResolved.push(...got.resolved);
  }

  const outfit: PartRef[] = [
    ref('f', 'fc_01', 'part_f_head_fc_01_head_se'),
    ref('f', 'ey_01', 'part_f_head_ey_01_head_se_neutral'),
    ref('f', 'mo_01', 'part_f_head_mo_01_head_se_neutral'),
    ref('f', 'fc_03', 'part_f_head_fc_03_head_se'),
    ref('f', 'ey_03', 'part_f_head_ey_03_head_se_neutral'),
    ref('f', 'mo_03', 'part_f_head_mo_03_head_se_neutral'),
    ref('f', 'no_01', 'part_f_head_no_01_head_se'),
  ];
  const combo = loader.validateOutfit(outfit);
  if (!combo.ok) {
    return caseResult('a', '挂入 face_redraw + E1 expand', 'accept', false, 'redraw_1110 组合被误拒', combo.issues, combo);
  }
  if (combo.resolved.some((row) => row.socketSet !== 'redraw_1110')) {
    return caseResult('a', '挂入 face_redraw + E1 expand', 'accept', false, '组合中出现非 redraw_1110', combo.issues, combo);
  }

  return caseResult(
    'a',
    '挂入 face_redraw + E1 expand',
    'accept',
    true,
    '29 条扩库 byId 命中；旧件 ey_01/mo_01/fc_01 按 entries 查到且缺 byId 不当失败；与扩库件均为 redraw_1110，组合合法。',
    [],
    {
      loader: loader.summary(),
      expandByIdHits: expandIds.length,
      oldLookups: oldResolved,
      outfit: combo.resolved,
    },
  );
}

/**
 * b) 未挂 face_redraw、仅 W2(+ne)+expand：不采预合并 byGenderPartSet；
 * 扩库 redraw_1110 与仍为 w2_legacy 的旧件组合应失败。
 */
function caseB(data: SelfcheckData): CaseResult {
  const loader = createLoader({
    manifest: data.manifest,
    compat: data.compat,
    legacyIds: data.legacyIds,
    loadOrder: LOAD_ORDER_WITHOUT_FACE_REDRAW,
  });

  const old = loader.resolve(ref('f', 'fc_01', 'part_f_head_fc_01_head_se'));
  const eye = loader.resolve(ref('f', 'ey_01', 'part_f_head_ey_01_head_se_neutral'));
  if (!old.ok || !eye.ok) {
    const issues = [...(!old.ok ? old.issues : []), ...(!eye.ok ? eye.issues : [])];
    return caseResult('b', '未挂 face_redraw 时混 socketSet', 'reject', true, '旧件查询失败，无法完成混挂检查', issues);
  }
  const preFc = loader.premergedSocketSet('f', 'fc_01');
  const preEy = loader.premergedSocketSet('f', 'ey_01');
  const actualFc = old.resolved[0]?.socketSet;
  const actualEy = eye.resolved[0]?.socketSet;
  if (actualFc !== 'w2_legacy' || actualEy !== 'w2_legacy') {
    return caseResult(
      'b',
      '未挂 face_redraw 时混 socketSet',
      'reject',
      actualFc === 'redraw_1110' && actualEy === 'redraw_1110',
      `未挂 face_redraw 时旧件应为 w2_legacy，实际 fc_01=${actualFc} ey_01=${actualEy}；预合并表为 fc_01=${preFc} ey_01=${preEy}。若采预合并会误判为 redraw_1110。`,
      [],
      { actualFc, actualEy, preFc, preEy, usedPremerged: loader.summary().usedPremergedByGenderPartSet },
      false,
    );
  }
  if (preFc !== 'redraw_1110' || preEy !== 'redraw_1110') {
    return caseResult(
      'b',
      '未挂 face_redraw 时混 socketSet',
      'reject',
      false,
      `对照用预合并表异常（期望仍为 redraw_1110 以便证明未误采），实际 fc_01=${preFc} ey_01=${preEy}`,
    );
  }

  const combo = loader.validateOutfit([
    ref('f', 'fc_01', 'part_f_head_fc_01_head_se'),
    ref('f', 'ey_01', 'part_f_head_ey_01_head_se_neutral'),
    ref('f', 'ey_03', 'part_f_head_ey_03_head_se_neutral'),
    ref('f', 'no_01', 'part_f_head_no_01_head_se'),
  ]);
  const mixed = combo.issues.some((i) => i.code === 'MIXED_SOCKET_SET');
  if (combo.ok || !mixed) {
    return caseResult(
      'b',
      '未挂 face_redraw 时混 socketSet',
      'reject',
      combo.ok,
      '应当因混挂 w2_legacy 与 redraw_1110 失败，但未报 MIXED_SOCKET_SET',
      combo.issues,
      combo,
      false,
    );
  }
  return caseResult(
    'b',
    '未挂 face_redraw 时混 socketSet',
    'reject',
    false, // actualOutcome reject, expected reject → passed
    '未采预合并表（fc_01/ey_01 仍为 w2_legacy，预合并为 redraw_1110）；与扩库 redraw_1110 件组合正确报 MIXED_SOCKET_SET。',
    combo.issues,
    { loader: loader.summary(), premerged: { fc_01: preFc, ey_01: preEy }, combo },
  );
}

/** c) ey_02 / mo_02（预合并后仍为 w2_legacy）配到新脸 redraw_1110 上应失败。 */
function caseC(data: SelfcheckData): CaseResult {
  const loader = createLoader({
    manifest: data.manifest,
    compat: data.compat,
    legacyIds: data.legacyIds,
    loadOrder: LOAD_ORDER_WITH_FACE_REDRAW,
  });
  const preEy = loader.premergedSocketSet('f', 'ey_02');
  const preMo = loader.premergedSocketSet('f', 'mo_02');
  const ey = loader.validateOutfit([
    ref('f', 'fc_03', 'part_f_head_fc_03_head_se'),
    ref('f', 'ey_02', 'part_f_head_ey_02_head_se_neutral'),
  ]);
  const mo = loader.validateOutfit([
    ref('f', 'fc_03', 'part_f_head_fc_03_head_se'),
    ref('f', 'mo_02', 'part_f_head_mo_02_head_se_neutral'),
  ]);
  const eyMixed = ey.issues.some((i) => i.code === 'MIXED_SOCKET_SET');
  const moMixed = mo.issues.some((i) => i.code === 'MIXED_SOCKET_SET');
  if (ey.ok || mo.ok || !eyMixed || !moMixed) {
    return caseResult(
      'c',
      'ey_02/mo_02 配新脸',
      'reject',
      !!(ey.ok && mo.ok),
      `ey_02 配 fc_03 或 mo_02 配 fc_03 应当失败。ey_ok=${ey.ok} mo_ok=${mo.ok} premerged ey_02=${preEy} mo_02=${preMo}`,
      [...ey.issues, ...mo.issues],
      { ey, mo, preEy, preMo },
      false,
    );
  }
  return caseResult(
    'c',
    'ey_02/mo_02 配新脸',
    'reject',
    false,
    `ey_02、mo_02 预合并后仍为 w2_legacy（${preEy}/${preMo}），配到 fc_03（redraw_1110）正确报 MIXED_SOCKET_SET。`,
    [...ey.issues, ...mo.issues],
    { ey, mo, preEy, preMo },
  );
}

/** d) head_compat 缺某条扩库 id：校验失败，不默认填。 */
function caseD(data: SelfcheckData): CaseResult {
  const dropped = 'part_f_head_fc_03_head_se';
  const mutated: HeadCompat = {
    ...data.compat,
    byId: { ...data.compat.byId },
    expansionIdCount: data.compat.expansionIdCount,
  };
  delete mutated.byId[dropped];
  const loader = createLoader({
    manifest: data.manifest,
    compat: mutated,
    legacyIds: data.legacyIds,
    loadOrder: LOAD_ORDER_WITH_FACE_REDRAW,
  });
  const pkg = loader.validatePackage();
  const missing = pkg.issues.some((i) => i.code === 'COMPAT_MISSING_EXPAND_ID' && String(i.message).includes(dropped));
  if (pkg.ok || !missing) {
    return caseResult(
      'd',
      'head_compat 缺扩库 id',
      'reject',
      pkg.ok,
      '缺扩库 id 应当校验失败且不得默认填，但未报 COMPAT_MISSING_EXPAND_ID',
      pkg.issues,
      pkg,
      false,
    );
  }
  return caseResult(
    'd',
    'head_compat 缺扩库 id',
    'reject',
    false,
    `去掉 byId.${dropped} 后正确报 COMPAT_MISSING_EXPAND_ID，未默认填入。`,
    pkg.issues,
  );
}

/** e) append 与已有 id 冲突：校验失败。 */
function caseE(data: SelfcheckData): CaseResult {
  const conflictId = 'part_f_head_ey_01_head_se_neutral';
  const mutated: ExpandManifest = {
    ...data.manifest,
    parts: data.manifest.parts.map((p, i) =>
      i === 0 ? { ...p, id: conflictId } : p,
    ),
  };
  const loader = createLoader({
    manifest: mutated,
    compat: data.compat,
    legacyIds: data.legacyIds,
    loadOrder: LOAD_ORDER_WITH_FACE_REDRAW,
  });
  const pkg = loader.validatePackage();
  const conflict = pkg.issues.some((i) => i.code === 'APPEND_ID_CONFLICT' && String(i.message).includes(conflictId));
  if (pkg.ok || !conflict) {
    return caseResult(
      'e',
      'append 与已有 id 冲突',
      'reject',
      pkg.ok,
      '应当报 APPEND_ID_CONFLICT，但未报出',
      pkg.issues,
      pkg,
      false,
    );
  }
  return caseResult(
    'e',
    'append 与已有 id 冲突',
    'reject',
    false,
    `将清单首条 id 改为已有旧件 ${conflictId} 后，正确报 APPEND_ID_CONFLICT。`,
    pkg.issues,
  );
}

export function runSelfcheck(data: SelfcheckData): SelfcheckReport {
  const cases = [caseA(data), caseB(data), caseC(data), caseD(data), caseE(data)];
  const passedCount = cases.filter((c) => c.passed).length;
  const manifestMatch =
    data.sha256?.manifest != null ? data.sha256.manifest === EXPECTED_SHA256.parts_manifest_v1 : undefined;
  const compatMatch =
    data.sha256?.compat != null ? data.sha256.compat === EXPECTED_SHA256.head_compat_v1 : undefined;
  return {
    version: LOADER_VERSION,
    title: 'V1 五官扩充 E1 预览 · P1 加载框架自检（socketSet / byId，非验收）',
    note: 'P1 加载框架校验（沿用 a–e）；本文件只覆盖 socketSet/byId。§8.3 与 P2–P6 见 e1Selfcheck_MT.ts。数字不冻结，不报整包验收通过。',
    sha256: {
      manifest: data.sha256?.manifest,
      manifestExpected: EXPECTED_SHA256.parts_manifest_v1,
      manifestMatch,
      compat: data.sha256?.compat,
      compatExpected: EXPECTED_SHA256.head_compat_v1,
      compatMatch,
    },
    cases,
    allPassed: cases.every((c) => c.passed),
    passedCount,
    failedCount: cases.length - passedCount,
  };
}
