/**
 * socketSet 坐标（相对下巴 / head 原点）。
 * 只作对照，不写回 4177–4183 的 bones（那些包仍是 w2_legacy）。
 * 与 A0 head_compat_v1.json.socketSets 及平台 11:01 / A0 口径一致。
 */
import type { Gender, SocketSetName } from '../types_MT';

export interface SocketPairMap {
  eye_l: readonly [number, number];
  eye_r: readonly [number, number];
  mouth: readonly [number, number];
}

export const SOCKET_SETS: Record<SocketSetName, Record<Gender, SocketPairMap>> = {
  w2_legacy: {
    f: { eye_l: [-44.6, -136.4], eye_r: [44.6, -136.4], mouth: [0, -29.8] },
    m: { eye_l: [-44.6, -136.4], eye_r: [44.6, -136.4], mouth: [0, -29.8] },
  },
  redraw_1110: {
    f: { eye_l: [-39, -96], eye_r: [39, -96], mouth: [0, -35] },
    m: { eye_l: [-37, -103], eye_r: [37, -103], mouth: [0, -44] },
  },
};

/** 鼻点派生：nose = eye_mid + 0.62 × (mouth − eye_mid)。本框架只校验，不挂图。 */
export const NOSE_FORMULA_WEIGHT = 0.62;

export function derivedNose(set: SocketSetName, gender: Gender): [number, number] {
  const s = SOCKET_SETS[set][gender];
  const eyeMidX = (s.eye_l[0] + s.eye_r[0]) / 2;
  const eyeMidY = (s.eye_l[1] + s.eye_r[1]) / 2;
  return [
    eyeMidX + NOSE_FORMULA_WEIGHT * (s.mouth[0] - eyeMidX),
    eyeMidY + NOSE_FORMULA_WEIGHT * (s.mouth[1] - eyeMidY),
  ];
}

export const EXPECTED_NOSE: Record<Gender, readonly [number, number]> = {
  f: [0, -58.18],
  m: [0, -66.42],
};
